/* Bare Signals Blood Work data. Source: Cece's Bloodwork Encyclopedia (deep research, Apr-Oct 2026). */
window.BW_PEP=[{"name": "Semaglutide", "cat": "Weight Loss", "before": "Fasting glucose + insulin, HbA1C, liver (ALT/AST), pancreas (amylase/lipase), thyroid (TSH, FT3), B12, electrolytes (Na/K), lipids, kidney", "monitor": "Glucose, insulin, HbA1C, amylase/lipase (pancreatitis!), B12 (depletes!), electrolytes, uric acid, liver enzymes, thyroid if energy drops", "freq": "Every 3 months", "flags": "Severe abdominal pain (pancreatitis), B12 deficiency symptoms (tingling, brain fog), heart palpitations (electrolytes), thyroid fatigue (rT3 rising)"}, {"name": "Tirzepatide", "cat": "Weight Loss", "before": "Same as semaglutide + thyroid panel (C-cell tumor warning)", "monitor": "Same as semaglutide. Stronger metabolic effect = more aggressive monitoring needed", "freq": "Every 3 months", "flags": "Same as semaglutide but effects are stronger. Watch for rapid electrolyte depletion with aggressive weight loss."}, {"name": "Retatrutide", "cat": "Weight Loss", "before": "Fasting glucose + insulin, HbA1C, liver, pancreas (amylase/lipase), FULL thyroid (TSH/FT3/FT4/rT3), B12, electrolytes, lipids, kidney, uric acid, IGF-1 (if combining with GH peptides)", "monitor": "ALL of the above + uric acid (rapid fat loss → gout risk), rT3 (metabolic adaptation), heart rate (glucagon can increase), B12 every 3 months", "freq": "Every 3 months (uric acid monthly if rapid loss)", "flags": "Pancreatitis (severe belly pain), gout (sudden joint pain), metabolic adaptation (energy crash = check rT3), B12 depletion, electrolyte imbalance (palpitations)"}, {"name": "BPC-157", "cat": "Repair", "before": "Liver (ALT/AST), blood pressure baseline, CBC", "monitor": "Blood pressure (can change), liver enzymes, mood (affects serotonin pathways — watch if on SSRI)", "freq": "Every 3-6 months", "flags": "Blood pressure changes, mood shifts (especially if on SSRI/SNRI — can interact with serotonin), unusual fatigue"}, {"name": "TB-500", "cat": "Repair", "before": "CBC, hs-CRP (inflammation baseline), liver", "monitor": "CBC (immune modulation), hs-CRP (should improve), liver", "freq": "Every 3-6 months", "flags": "Unusual fatigue, immune changes"}, {"name": "GHK-Cu", "cat": "Skin/Longevity", "before": "IGF-1 (GH axis baseline), copper levels (copper peptide!), liver", "monitor": "IGF-1 (tracks effectiveness), copper if prolonged use, liver", "freq": "Every 3-6 months", "flags": "Copper sensitivity reactions, blood pressure changes"}, {"name": "MOTS-C", "cat": "Longevity", "before": "Fasting glucose + insulin, IGF-1, hs-CRP, lipids, HbA1C", "monitor": "IGF-1 (tracks GH axis), glucose/insulin (AMPK effect), hs-CRP (inflammation should drop), lipids", "freq": "Every 3-6 months", "flags": "Fluid retention, blood sugar changes, GI upset"}, {"name": "Ipamorelin", "cat": "GH Secretagogue", "before": "IGF-1 (baseline!), fasting glucose + insulin, liver, cortisol", "monitor": "IGF-1 (must track — this IS the point), fasting glucose (GH raises glucose), cortisol (should NOT rise — that is the advantage over GHRP-2/6)", "freq": "IGF-1: monthly for first 3 months, then quarterly", "flags": "IGF-1 going too high (above 300 = cancer concern), glucose rising, brief tachycardia after injection"}, {"name": "CJC-1295 (no DAC)", "cat": "GH Amplifier", "before": "Same as ipamorelin — they are always used together", "monitor": "Same as ipamorelin. IGF-1 + glucose + insulin", "freq": "Same as ipamorelin", "flags": "Same as ipamorelin. Water retention, tingling (common, not dangerous)"}, {"name": "CJC-1295 (with DAC)", "cat": "GH (Long-acting)", "before": "Same as no-DAC + extra caution with insulin sensitivity (sustained GH elevation)", "monitor": "IGF-1 (will be chronically elevated, not pulsed), fasting insulin (sustained GH = insulin resistance risk)", "freq": "Monthly IGF-1 for first 3 months", "flags": "Chronically elevated IGF-1 (above 300), insulin resistance developing, water retention, joint pain"}, {"name": "GHRP-2", "cat": "GH Secretagogue", "before": "IGF-1, cortisol, prolactin, fasting glucose", "monitor": "IGF-1, cortisol (GHRP-2 raises it!), prolactin (GHRP-2 raises it!), glucose", "freq": "Every 3 months", "flags": "Rising cortisol, elevated prolactin (check for symptoms: missed periods, libido changes), glucose creeping up"}, {"name": "GHRP-6", "cat": "GH Secretagogue", "before": "Same as GHRP-2 + be prepared for massive appetite increase", "monitor": "Same as GHRP-2 but cortisol spike is MORE significant", "freq": "Every 3 months", "flags": "Uncontrollable hunger (not a biomarker but a real side effect), cortisol elevation, weight gain from eating more"}, {"name": "HGH (Somatropin)", "cat": "Growth Hormone", "before": "IGF-1, fasting glucose + insulin, HbA1C, liver, thyroid, lipids, FULL metabolic panel", "monitor": "IGF-1 (critical — must stay below 300), fasting insulin (HGH CAUSES insulin resistance), glucose, HbA1C, liver enzymes", "freq": "Monthly for first 3 months, then quarterly", "flags": "IGF-1 above 300 (cancer risk), developing insulin resistance/diabetes, joint pain (acromegaly signs), carpal tunnel, edema"}, {"name": "Tesamorelin", "cat": "GH (Visceral Fat)", "before": "IGF-1, fasting glucose (can raise!), liver, visceral fat baseline (DEXA)", "monitor": "IGF-1, fasting glucose (tesamorelin can raise blood sugar!), heart rate, liver", "freq": "Every 3 months", "flags": "Blood sugar rising, night sweats, heart rate increase, joint pain"}, {"name": "MK-677 (Ibutamoren)", "cat": "GH (Oral)", "before": "IGF-1, fasting glucose + insulin (CRITICAL — MK-677 raises both!), HbA1C, liver", "monitor": "IGF-1, fasting glucose + insulin (monitor closely — this is MK-677s biggest risk), HbA1C, appetite tracking", "freq": "Monthly glucose for first 3 months, then quarterly", "flags": "Blood sugar creeping up (MK-677 WILL raise fasting glucose in many people), pre-diabetes developing, massive appetite increase, water retention"}, {"name": "Epithalon", "cat": "Longevity", "before": "CBC, liver, heart rhythm (ECG if available)", "monitor": "CBC, liver enzymes, sleep quality tracking, telomere length (if doing advanced testing)", "freq": "After each 10-20 day cycle", "flags": "Irregular heartbeat, flu-like symptoms, fatigue (common during cycle)"}, {"name": "Thymosin Alpha-1", "cat": "Immune", "before": "CBC with differential, hs-CRP, liver, kidney", "monitor": "CBC (WBC differential — watching T-cell activation), hs-CRP, liver", "freq": "Every 3 months", "flags": "Fever, fatigue, low WBC (paradoxical immune suppression), nausea"}, {"name": "PT-141", "cat": "Sexual", "before": "Blood pressure baseline", "monitor": "Blood pressure (can raise), skin pigmentation with repeated use", "freq": "As needed (not regular)", "flags": "Blood pressure spike, severe nausea (common — take anti-nausea beforehand), skin darkening"}, {"name": "Semax", "cat": "Cognitive", "before": "Blood glucose (if diabetic), CBC", "monitor": "Blood glucose (can raise in diabetics), mood and cognition tracking (subjective)", "freq": "Every 3-6 months", "flags": "Blood sugar increase (diabetics), hair loss (rare), nasal irritation"}, {"name": "Selank", "cat": "Cognitive", "before": "CBC, liver", "monitor": "CBC (immune modulation), mood tracking", "freq": "Every 3-6 months", "flags": "Fatigue, headaches, nasal irritation, mood changes"}, {"name": "NAD+ (injectable)", "cat": "Longevity", "before": "Fasting insulin, platelets, liver, phosphorus", "monitor": "Fasting insulin (can decrease sensitivity paradoxically), platelets (can decrease), phosphorus", "freq": "Every 3 months", "flags": "Headaches, nausea, platelet drop, phosphorus depletion"}, {"name": "Melanotan II", "cat": "Tanning/Libido", "before": "Full skin check with dermatologist (mole mapping!), blood pressure", "monitor": "SKIN CHECK (moles darken — need to distinguish darkened benign moles from melanoma!), blood pressure", "freq": "Skin: every 3-6 months while on it", "flags": "New or changing moles (GET CHECKED — melanoma risk is the real concern), blood pressure changes, persistent nausea"}, {"name": "EPO", "cat": "Performance", "before": "CBC with hematocrit (CRITICAL), iron + ferritin, blood pressure, kidney function", "monitor": "Hematocrit (MUST stay below 50% — above = blood too thick = stroke/heart attack risk!), blood pressure, iron/ferritin", "freq": "Hematocrit: every 2-4 weeks while on", "flags": "Hematocrit above 50% = STOP immediately. Blood too thick. Headaches, vision changes, chest pain = emergency"}, {"name": "Glutathione (IV)", "cat": "Antioxidant", "before": "Zinc (glutathione can deplete zinc), liver", "monitor": "Zinc levels with chronic use, liver enzymes", "freq": "Every 3-6 months", "flags": "Zinc depletion symptoms (immune dysfunction, skin issues), abdominal cramps"}, {"name": "L-Carnitine (inject)", "cat": "Metabolic", "before": "Thyroid (supports T4→T3 conversion), electrolytes", "monitor": "Thyroid function, electrolytes, body odor (fishy smell = sign of excess)", "freq": "Every 6 months", "flags": "GI issues, muscle cramps, fishy body odor"}, {"name": "Orforglipron", "cat": "Oral GLP-1", "before": "Same as semaglutide (it IS a GLP-1 agonist, just oral)", "monitor": "Same monitoring as semaglutide + kidney function (dehydration risk higher with oral form)", "freq": "Every 3 months", "flags": "Same as semaglutide plus acute kidney injury from dehydration"}];
window.BW_TEST=[{"n": "Fasting Glucose", "cat": "SUGAR & ENERGY", "what": "This is literally how much sugar is floating in your blood right now after not eating for 8+ hours. Think of it like checking the water level in a pool when nobody is swimming — it shows you the \"resting\" level of sugar your body maintains.", "feel": "If HIGH: you might not feel anything yet, that is the scary part. Over time: constant thirst, peeing a lot, fatigue after meals, brain fog, blurry vision. If very high: you are on the road to diabetes.\nIf LOW: shaky, dizzy, anxious, sweaty, hangry, brain feels like it is shutting off. Your body is screaming \"feed me.\"", "range": "GOOD: 70-85 mg/dL\nOKAY: 86-99\nRED FLAG: 100-125 (pre-diabetic)\nDANGEROUS: 126+ (diabetic)\n\nLab says \"normal\" up to 100 but anything above 85 already deserves attention.", "fast": "YES. Must fast\n8-12 hours.", "retest": "Every 3 months\non reta", "one": "This is the most basic sugar test. But fasting INSULIN (below) is actually more important because it catches problems 5-10 YEARS earlier. Always test both together."}, {"n": "Fasting Insulin", "cat": "SUGAR & ENERGY", "what": "Insulin is the HORMONE that takes sugar out of your blood and pushes it into your cells for energy. Think of insulin as a delivery driver. This test measures how many delivery drivers your body has to send out just to keep sugar levels normal.\n\nIf your body needs to send 15 drivers to do a job that should only take 3, that means your cells are ignoring the deliveries (insulin resistance). The sugar gets delivered eventually, so glucose looks \"normal,\" but the system is overworking.", "feel": "You would NOT feel this directly, that is why it is so dangerous. Insulin resistance builds silently for YEARS before glucose goes up. But indirect signs: stubborn belly fat that will not budge no matter what you do, energy crashes after meals, sugar cravings, brain fog after eating carbs, dark patches on neck/armpits (acanthosis nigricans), difficulty losing weight, PCOS symptoms.", "range": "OPTIMAL: 2-5 μIU/mL\nACCEPTABLE: 6-8\nRED FLAG: 9-15\nBAD: 16-25 (lab says \"normal\" up to 25 but this is already deep insulin resistance)\n\nMost doctors do NOT test this. They only test glucose. Insist on it.", "fast": "YES. Must fast\n8-12 hours.\nMorning draw.", "retest": "Every 3 months", "one": "THIS IS THE MOST IMPORTANT TEST MOST PEOPLE HAVE NEVER HEARD OF. Your glucose can look perfect while insulin is screaming. A fasting insulin of 12 with a glucose of 85 means you are insulin resistant even though a doctor would say \"everything is fine.\""}, {"n": "HbA1C", "cat": "SUGAR & ENERGY", "what": "Think of this as your blood sugar GPA over the last 3 months. While fasting glucose is one exam score, HbA1C is your semester average. It measures how much sugar has been \"stuck\" to your red blood cells over their 90-day lifespan.\n\nSugar is sticky. The more sugar in your blood over time, the more gets stuck to your blood cells. This test counts how many of your blood cells are sugar-coated.", "feel": "Same as glucose — you might not feel anything until it is quite high. This is a slow-burn marker. By the time you feel symptoms from a high A1C, damage has been happening for months or years.", "range": "OPTIMAL: below 5.0%\nGOOD: 5.0-5.4%\nPRE-DIABETIC: 5.5-6.4%\nDIABETIC: 6.5%+\n\nEvery 0.1% matters. Going from 5.3% to 4.9% is a meaningful improvement.", "fast": "NO. This is one\ntest you can do\nany time of day,\nfed or fasted.", "retest": "Every 3 months", "one": "This is the most reliable diabetes marker because it cannot be faked by one day of good eating. It shows what your body has really been doing for 3 months."}, {"n": "C-Peptide", "cat": "SUGAR & ENERGY", "what": "When your pancreas makes insulin, it also releases C-peptide as a byproduct — exactly 1:1. Think of C-peptide as the receipt for every insulin delivery. By counting receipts, we know exactly how much insulin your pancreas MADE (not how much is floating around, which can include injected insulin).\n\nThis is a deeper, more precise version of the insulin test.", "feel": "You would not feel C-peptide itself. It is a diagnostic tool, not something that causes symptoms. But what it reveals — whether your pancreas is working too hard or not hard enough — has major implications.", "range": "OPTIMAL: 0.8-2.0 ng/mL\nLAB NORMAL: 1.1-4.4\n\nHigh = pancreas overworking (insulin resistance)\nLow = pancreas underperforming (possible T1D or burnout)", "fast": "YES. Fast 8-12hr.", "retest": "Baseline only", "one": "Most panels do not include this. The fact that Human+ includes it is genuinely impressive — it is a precision marker most boutique wellness panels skip."}, {"n": "HOMA-IR (you calculate this yourself)", "cat": "SUGAR & ENERGY", "what": "This is not a blood test — it is a formula you calculate from two tests you already have. It gives you ONE single number for insulin resistance.\n\nFormula: (Fasting Glucose in mg/dL × Fasting Insulin in μIU/mL) ÷ 405\n\nExample: Glucose 85 × Insulin 5 = 425 ÷ 405 = 1.05 → excellent\nExample: Glucose 95 × Insulin 12 = 1140 ÷ 405 = 2.8 → you are insulin resistant", "feel": "N/A — this is a calculation, not something you feel. But the number it produces tells you clearly whether your metabolism is healthy or heading toward trouble.", "range": "OPTIMAL: below 1.0\nGOOD: 1.0-1.4\nRED FLAG: 1.5-2.0\nINSULIN RESISTANT: above 2.0\nSEVERE: above 3.0", "fast": "N/A", "retest": "Every 3 months\n(recalculate)", "one": "This is the single most useful number you can derive from basic blood work. Grab a calculator after you get your H+ results: (glucose × insulin) ÷ 405. Write this number down. It is your metabolic health score."}, {"n": "ApoB", "cat": "HEART & CHOLESTEROL", "what": "Forget everything you have been told about \"good cholesterol\" and \"bad cholesterol.\" ApoB is the actual number that matters.\n\nEvery dangerous cholesterol particle in your blood has exactly ONE ApoB protein on it — like a name tag. So counting ApoB = counting the actual number of particles that can burrow into your artery walls and build plaque.\n\nLDL cholesterol measures the WEIGHT of cholesterol on those particles. ApoB counts the PARTICLES THEMSELVES. You can have low LDL weight but lots of small dense particles (high ApoB) = high risk. Or high LDL weight but few large fluffy particles (low ApoB) = lower risk.", "feel": "You feel NOTHING. That is the terrifying part. Cardiovascular disease builds silently for decades. By the time you feel chest pain or shortness of breath, you have significant plaque buildup. ApoB tells you your risk 20-30 years before symptoms appear.", "range": "OPTIMAL: below 70 mg/dL\nACCEPTABLE: 70-90\nELEVATED: 90-120\nHIGH RISK: above 120\n\nLongevity doctors like Peter Attia consider this THE most important blood marker, period.", "fast": "YES. Fast 8-12hr.", "retest": "Every 6-12\nmonths", "one": "If you only track ONE number for heart health, this is it. Not total cholesterol. Not LDL. ApoB. Peter Attia calls it \"the most important blood biomarker.\" Ask for it by name."}, {"n": "Lipoprotein(a) — Lp(a)", "cat": "HEART & CHOLESTEROL", "what": "This is a special type of cholesterol particle that is almost entirely determined by your GENETICS. You are born with your Lp(a) level and no amount of diet, exercise, or lifestyle change will significantly move it.\n\nThink of it as a genetic lottery for heart disease risk. Some people have very low Lp(a) (lucky). Some have very high (unlucky). Most people have never been tested and have no idea which group they are in.", "feel": "You feel nothing. But if your Lp(a) is high, your lifetime risk of heart attack and stroke is significantly elevated — INDEPENDENT of everything else. You could have perfect LDL, perfect ApoB, perfect blood pressure, and still be at higher risk because of Lp(a).", "range": "IDEAL: below 30 nmol/L\nACCEPTABLE: 30-50\nELEVATED: 50-75\nHIGH RISK: above 75", "fast": "YES. Fast.", "retest": "ONCE in your\nentire life.\nIt is genetic —\nit does not change.", "one": "You only need this test ONE TIME EVER. The result is permanent because it is written in your DNA. But knowing it can literally change your entire cardiovascular strategy for life. Most people have never been tested."}, {"n": "TSH", "cat": "THYROID", "what": "Your thyroid is a small butterfly-shaped gland in your neck that controls your ENTIRE metabolism — how fast you burn calories, your body temperature, your energy levels, your mood, your hair growth, your digestion speed, everything.\n\nTSH is NOT a thyroid hormone. It is a signal from your BRAIN telling your thyroid how hard to work. Think of TSH as your brain yelling instructions:\n\n- Brain yells loudly (HIGH TSH) = \"Hey thyroid, WORK HARDER, you are not producing enough!\"\n- Brain whispers (LOW TSH) = \"Calm down thyroid, you are producing too much!\"", "feel": "HIGH TSH (hypothyroid = slow thyroid):\nFatigue that sleep does not fix, weight gain despite eating the same, feeling cold when others are fine, constipation, dry skin, hair falling out more than usual, brain fog, depression, puffy face, slow heart rate.\n\nLOW TSH (hyperthyroid = overactive thyroid):\nAnxiety, heart racing, weight loss without trying, feeling hot, trembling hands, insomnia, diarrhea, irritability.", "range": "OPTIMAL: 0.5-2.0 mIU/L\nLAB \"NORMAL\": 0.4-4.5\n\nHere is the problem: labs say anything up to 4.5 is \"normal.\" But many people with TSH of 3.0-4.5 have hypothyroid symptoms and feel terrible. Most people feel best between 0.5-2.0. If your doctor says your TSH of 3.8 is \"fine\" but you feel exhausted with hair falling out, push back.", "fast": "No. But morning\nis better for\nconsistency.", "retest": "Every 3 months\non reta", "one": "TSH alone is NOT enough. It is like checking the thermostat setting without checking the actual room temperature. You MUST also test Free T3 and Free T4 (below) to see if thyroid hormones are actually being produced and used correctly."}, {"n": "Free T3", "cat": "THYROID", "what": "If TSH is your brain yelling at your thyroid, Free T3 is what your thyroid actually DELIVERS. T3 is the ACTIVE thyroid hormone — the one that actually enters your cells and drives your metabolism.\n\nYour thyroid mostly produces T4 (inactive, like a precursor). Your body then converts T4 → T3 (active) in your liver, gut, and tissues. Free T3 measures how much active hormone is available RIGHT NOW.\n\nThis is the most undertested thyroid marker. Many people have \"normal\" TSH but LOW Free T3, which means their thyroid is technically working but the conversion to the active form is broken.", "feel": "Low Free T3 feels like hypothyroid even if TSH is normal: tired, cold, brain foggy, hair thinning, weight creeping up, can not lose fat despite doing everything right, slow recovery from workouts, low motivation.\n\nHigh Free T3: anxious, wired, heart racing, losing weight too fast, can not sleep.", "range": "OPTIMAL: 3.0-4.0 pg/mL\nLAB \"NORMAL\": 2.0-4.4\n\nBelow 3.0 with symptoms = you have a conversion problem even if TSH looks fine.", "fast": "No. Morning\npreferred.", "retest": "Every 3 months\non reta", "one": "This is the thyroid test most doctors skip and most patients have never heard of. You can have perfect TSH and still feel hypothyroid because your body is not converting T4 to T3 properly. Selenium and zinc are the two cheapest fixes."}, {"n": "Reverse T3 (rT3)", "cat": "THYROID", "what": "Your body can convert T4 into either:\n- Free T3 (the gas pedal — speeds up metabolism)\n- Reverse T3 (the BRAKE pedal — slows down metabolism)\n\nReverse T3 looks like T3 but does the OPPOSITE. It plugs into the same receptors in your cells but blocks them instead of activating them. It is like someone putting a fake key into your car ignition — takes up the slot but does not start the engine.\n\nYour body makes more Reverse T3 when it thinks you are in danger or starving. It is a survival mechanism: \"Food is scarce, slow everything down to conserve energy.\"", "feel": "Same symptoms as low Free T3 (because rT3 is blocking T3 from working): fatigue, cold, brain fog, weight gain or inability to lose weight, slow recovery — EVEN IF your TSH and T4 look perfectly normal on paper.\n\nThis is the \"hidden\" thyroid problem. Everything looks normal on standard tests but you feel terrible.", "range": "OPTIMAL: below 15 ng/dL\n\nMore important: the RATIO of Free T3 to Reverse T3 (FT3 ÷ rT3). If this ratio is below 0.2, your body is in metabolic conservation mode — pressing the brakes on your metabolism.", "fast": "No. Morning.", "retest": "Every 3 months\non reta", "one": "This test costs Rp 600K-1M and most labs do not stock it. But it is THE test that explains why some people hit a wall on reta despite eating barely anything. If your FT3:rT3 ratio drops below 0.2, you need to eat more, not less."}, {"n": "Anti-TPO (Thyroid Peroxidase Antibodies)", "cat": "THYROID", "what": "Antibodies are soldiers your immune system makes to attack foreign invaders (viruses, bacteria). But sometimes your immune system gets confused and makes antibodies that attack your OWN body. When this happens to your thyroid, it is called Hashimotos thyroiditis.\n\nAnti-TPO measures whether your immune system is currently attacking your thyroid. The tricky part: this attack can happen for 5-10 YEARS before your thyroid actually fails and TSH goes up. So your thyroid numbers can look \"fine\" while it is slowly being destroyed.\n\n1 in 5 women test positive for Anti-TPO.", "feel": "In early stages: nothing. You feel completely normal while your immune system is quietly damaging your thyroid.\n\nOver years: gradually developing hypothyroid symptoms — fatigue, weight gain, hair loss, cold intolerance, brain fog. Often happens so slowly you think it is \"just aging\" or \"just stress.\"", "range": "OPTIMAL: below 9 IU/mL\nLAB \"NORMAL\": below 34\n\nANY elevation means your immune system is attacking your thyroid. Even 15 is meaningful.", "fast": "No.", "retest": "ONCE.\nIf positive:\nannually.", "one": "1 in 5 women are positive. If you are, it does not mean you need medication NOW — it means you need to watch your thyroid more carefully and take selenium 200mcg daily. Two Brazil nuts per day provides enough selenium naturally."}, {"n": "IGF-1 (Insulin-like Growth Factor)", "cat": "HORMONES", "what": "Growth hormone (GH) is released by your brain, mostly during deep sleep. But GH itself is hard to measure because it comes in pulses — high one hour, gone the next.\n\nIGF-1 is what your liver produces in RESPONSE to growth hormone. It is the stable, measurable downstream effect. Think of GH as lightning (brief, unpredictable) and IGF-1 as the thunder (consistent, measurable).\n\nIGF-1 drives: muscle growth, tissue repair, bone strength, skin quality, fat burning, recovery from exercise, and cellular regeneration.", "feel": "LOW IGF-1: poor recovery from workouts, slow wound healing, losing muscle despite training, aging faster (wrinkles, thin skin, low energy), poor sleep quality, increased body fat especially around midsection, low mood.\n\nHIGH IGF-1: can be good (your GH axis is working well) but chronically very high levels over years may slightly increase certain cancer risks.", "range": "OPTIMAL for age 30: 150-250 ng/mL\nLAB RANGE: 115-307 (age-adjusted)\n\nBelow 150 at your age = your growth hormone axis is underperforming.", "fast": "YES. Fast.\nMorning draw.", "retest": "Every 3 months", "one": "Non-negotiable addition to your panel. Without this, half your peptide protocol is unmonitored. Ask Helix Bali to add it — probably costs Rp 400-800K. The fact that H+ charges Rp 22M and does not include the one marker you need most for your protocol is a legitimate criticism."}, {"n": "Cortisol (AM + PM)", "cat": "HORMONES", "what": "Cortisol is your stress hormone. It is not a villain — you NEED it. It wakes you up in the morning, gives you energy, helps you respond to danger, and regulates blood sugar.\n\nThe problem is the PATTERN. Cortisol should be:\n- HIGH in the morning (wakes you up, gives you drive)\n- LOW at night (lets you wind down and sleep)\n\nThis is called your \"diurnal curve.\" When this curve flattens — cortisol stays high at night or drops too low in the morning — everything breaks: sleep, weight, mood, immune function, hormone balance.\n\nH+ tests cortisol TWICE (morning AND afternoon), which gives you the curve shape, not just a snapshot. This is a premium feature most panels skip.", "feel": "HIGH CORTISOL (chronic stress):\nBelly fat that will not go away, trouble falling asleep despite being tired, anxiety, sugar cravings, puffy face, easy bruising, muscle weakness, irregular periods, acne.\n\nLOW CORTISOL (adrenal fatigue/burnout):\nCannot get out of bed, extreme fatigue, low blood pressure, dizzy when standing up, craving salt, feeling like you have been hit by a truck every morning, complete lack of motivation.", "range": "AM (7-9am): 10-20 mcg/dL\nPM (3-5pm): 3-10 mcg/dL\n\nThe RATIO matters more than individual numbers. AM should be 2-3x higher than PM.", "fast": "YES for AM\n(fasted, 7-9am)\nNo for PM.", "retest": "Every 6 months", "one": "The fact that H+ tests both AM and PM is genuinely valuable. Most panels only test morning cortisol, which is like checking the weather at noon and assuming you know the whole day. The PM draw shows whether your cortisol is properly declining or staying elevated (which destroys sleep quality)."}, {"n": "AMH (Anti-Mullerian Hormone)", "cat": "HORMONES", "what": "AMH measures your ovarian reserve — basically, how many eggs you have left. Every woman is born with all the eggs she will ever have (about 1-2 million). By puberty it is down to ~400,000. By 30 it is ~25,000-50,000. By 40 it is ~5,000.\n\nAMH does not tell you about egg QUALITY (that is separate). It tells you about egg QUANTITY. Think of it like a fuel gauge — it shows you how much is in the tank, not whether the fuel is premium or regular.\n\nThis is the most important test for understanding your reproductive timeline, even if you are not planning kids right now.", "feel": "You feel nothing from AMH itself. But what it reveals has massive implications: if AMH is very low at 30, your window for biological children is shorter than average. If AMH is very high, you might have PCOS (polycystic ovarian syndrome — the ovaries have too many follicles competing).", "range": "VERY GOOD at age 30: above 2.0 ng/mL\nGOOD: 1.0-2.0\nDIMINISHED: 0.5-1.0\nLOW: below 0.5\n\nVERY HIGH (above 4-5): suggests PCOS", "fast": "No.\nAny time of day.\nAny cycle day.", "retest": "Every 2-3 years\n(or once for\nbaseline)", "one": "Unlike every other hormone, AMH does NOT fluctuate with your menstrual cycle. You can test it any day, any time. It is the one hormone you do not need to time. At 30, this is pure baseline intelligence — knowledge about your body even if kids are not on the radar right now."}, {"n": "ALT (SGPT)", "cat": "LIVER", "what": "Your liver is the factory that processes EVERYTHING: medications, alcohol, supplements, peptides, hormones, toxins, fat. ALT is an enzyme that lives inside liver cells. When liver cells are damaged or inflamed, they leak ALT into your blood.\n\nThink of ALT as a smoke detector for your liver. If ALT is elevated, something is irritating or damaging your liver cells. The higher it is, the more cells are leaking.", "feel": "You feel NOTHING from mild liver irritation. The liver has no pain nerves — it can be significantly damaged before you notice anything. By the time you feel liver symptoms (yellowing skin, dark urine, right-side abdominal pain), it is advanced.\n\nThis is why testing is critical. The liver suffers silently.", "range": "OPTIMAL: below 20 U/L\nLAB \"NORMAL\": 7-35\n\nIMPORTANT: Labs say up to 35 is fine. But research shows that women with ALT above 25 have significantly higher risk of liver disease. Optimal is below 20.", "fast": "No.", "retest": "Every 3-6 months", "one": "Your liver processes all five of your peptides plus your supplements (creatine, whey, collagen, D3, magnesium). That is a real workload. NAC 600mg daily is cheap insurance — it is the precursor to glutathione, your liver is primary detox molecule. You already have it on your to-source list."}, {"n": "Amylase + Lipase (PANCREAS)", "cat": "LIVER", "what": "These are not actually liver tests — they are PANCREAS tests. But they are grouped here because the pancreas sits right next to the liver and both are digestive organs.\n\nAmylase and lipase are enzymes your pancreas makes to digest food. When the pancreas is inflamed (pancreatitis), these enzymes leak into the blood — just like ALT leaks when the liver is damaged.\n\nPancreatitis is a KNOWN (rare but real) side effect of GLP-1 agonist drugs like semaglutide, tirzepatide, and retatrutide.", "feel": "PANCREATITIS SYMPTOMS:\nSevere upper abdominal pain that radiates to your back, pain that gets worse after eating, nausea and vomiting, fever, rapid pulse, tender abdomen.\n\nThis is a MEDICAL EMERGENCY. If you experience sudden severe abdominal pain on reta and these numbers are very high, go to the ER immediately.", "range": "AMYLASE: 28-100 U/L\nLIPASE: 0-60 U/L\n\nAmylase >3x normal + symptoms = likely pancreatitis\nLipase is more specific and stays elevated longer", "fast": "No.", "retest": "Every 3 months\nwhile on reta", "one": "The fact that H+ does not include pancreatic safety markers while you are on a GLP-1 agonist is a legitimate safety gap. Add amylase + lipase. They cost maybe Rp 200-400K total at Prodia. Non-negotiable."}, {"n": "hs-CRP", "cat": "INFLAMMATION", "what": "CRP (C-Reactive Protein) is a protein your liver pumps out whenever there is inflammation ANYWHERE in your body. It is like a fire alarm — it does not tell you WHERE the fire is, but it tells you THAT there is a fire.\n\n\"hs\" stands for \"high-sensitivity\" — meaning the test can detect very small amounts of inflammation, not just the big obvious kind you get from an infection.\n\nChronic low-grade inflammation is now understood to be the ROOT DRIVER of aging, heart disease, cancer, Alzheimers, diabetes, and autoimmune disease. It is the background hum that accelerates everything bad.", "feel": "You probably feel nothing from mild chronic inflammation. Or you attribute it to other things: \"I am just tired,\" \"I am getting older,\" \"my joints are a bit stiff,\" \"I do not recover from workouts like I used to.\"\n\nThese vague complaints are often inflammation talking.", "range": "EXCELLENT: below 0.5 mg/L\nOPTIMAL: below 1.0\nELEVATED: 1.0-3.0\nHIGH: above 3.0\nACUTE INFECTION: above 10 (retest when healthy)\n\nIf your CRP is above 10, you are probably fighting an acute infection — this is not chronic inflammation, it is your body doing its job. Retest when you are well.", "fast": "No.", "retest": "Every 3-6 months", "one": "If your hs-CRP is above 1.0, do not just note it and move on. FIND THE SOURCE. Is it dental? Is it visceral fat? Is it stress? Is it poor sleep? Is it gut issues? Inflammation is not a diagnosis — it is a signal that something else is wrong. Track it over time to see if your protocol reduces it."}, {"n": "Vitamin B12", "cat": "VITAMINS", "what": "B12 is essential for energy production, nerve function, DNA synthesis, and making red blood cells. It is stored in your liver and can last for years — which means deficiency develops SLOWLY and is often missed until nerve damage has already occurred.\n\nYour body cannot make B12. It comes from animal products (meat, fish, eggs, dairy) or supplements.", "feel": "DEFICIENCY symptoms sneak up on you over months:\nFatigue that does not improve with sleep, brain fog and poor memory, tingling or numbness in hands/feet (nerve damage — can become PERMANENT if untreated), depression, mouth sores, pale or yellowish skin, balance problems, weakness.\n\nThe nerve symptoms are the scary ones. B12 deficiency can cause irreversible nerve damage if it goes on too long.", "range": "OPTIMAL: above 500 pg/mL\nFUNCTIONAL DEFICIENCY: 200-500 (you might have symptoms even though lab says \"normal\")\nCLINICAL DEFICIENCY: below 200\n\nLab \"normal\" starts at 200 but neurological symptoms can begin below 500. Most doctors do not flag B12 until it hits 200, by which point damage may have already started.", "fast": "No.", "retest": "Every 3 months\nwhile on reta", "one": "Reta will deplete your B12 over time. This is not speculation — it is documented pharmacology of GLP-1 agonists. Start supplementing methylcobalamin now if you have not already. Sublingual 1000mcg daily. Test every 3 months. If below 500, increase dose or switch to injections."}, {"n": "Ferritin", "cat": "VITAMINS", "what": "Ferritin is a protein that STORES iron inside your cells — like a warehouse. Testing ferritin tells you how full your iron warehouse is.\n\nBut ferritin has a dual identity: it is also an inflammation marker. When your body is inflamed, ferritin rises regardless of iron status. So you need to interpret ferritin alongside hs-CRP to know if it is reflecting true iron stores or just inflammation.\n\nIron is critical for: carrying oxygen to every cell in your body, energy production, exercise performance, hair growth, immune function, thyroid function, and brain function.", "feel": "LOW FERRITIN (even without full anemia):\nExhausted despite sleeping enough, cannot finish workouts that used to be easy, hair falling out more than usual (this is often the FIRST sign), feeling cold, restless legs at night, brittle nails, pale skin, brain fog, shortness of breath during exercise.\n\nHIGH FERRITIN:\nUsually means inflammation or iron overload. Joint pain, fatigue, abdominal pain, dark skin.", "range": "OPTIMAL for women: 50-100 ng/mL\nFUNCTIONAL DEFICIENCY: 30-50 (symptoms can start here)\nDEFICIENT: below 30\nLAB \"NORMAL\": 12-150\n\nHere is the gap: labs say 12 is \"normal.\" But hair loss and fatigue commonly start below 40. Most women feel best above 50.", "fast": "YES. Fast.\nMorning.", "retest": "Every 3-6 months", "one": "Hair loss? Check ferritin FIRST. It is the most common missed cause of hair loss in women and the easiest to fix. Most dermatologists go straight to minoxidil without checking iron. Target above 50 ng/mL for hair regrowth. Above 70 is even better."}, {"n": "Electrolytes (Na/K/Cl)", "cat": "KIDNEY", "what": "Sodium, potassium, and chloride are minerals that carry electrical charges in your body. They are literally what makes your heart beat in rhythm, your muscles contract, your nerves fire, and your cells maintain the right amount of water.\n\nThey are the most boring-sounding tests and simultaneously the most immediately dangerous if off. Low potassium can cause a fatal heart arrhythmia. This is not a theoretical risk — it happens.\n\nYour kidneys regulate electrolytes by deciding how much to keep and how much to pee out. When you eat less (as on reta), you take in fewer electrolytes. When you sweat (training in Bali heat), you lose more.", "feel": "LOW POTASSIUM (most dangerous):\nMuscle cramps, weakness, heart palpitations, irregular heartbeat, fatigue, constipation. SEVERE: cardiac arrest.\n\nLOW SODIUM:\nConfusion, headache, nausea, muscle cramps, seizures in extreme cases.\n\nHIGH POTASSIUM (also dangerous):\nWeakness, irregular heartbeat, can be life-threatening with kidney disease.", "range": "SODIUM: 136-145 mEq/L\nPOTASSIUM: 3.5-5.0\nCHLORIDE: 98-106\n\nPotassium below 3.5 OR above 5.5 = urgent medical attention needed.", "fast": "No.", "retest": "Every 3 months\non reta", "one": "If you feel heart palpitations or unusual muscle cramps on reta, do NOT just assume it is anxiety. Get electrolytes checked the same day. Low potassium is a medical emergency that is easily fixed with supplementation but dangerous if ignored. Coconut water daily is cheap prevention in Bali."}, {"n": "Total Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "Grand total of ALL cholesterol. Like knowing total cars on highway without knowing which are ambulances (good) vs drunk drivers (bad). Not useful alone — need the breakdown.", "feel": "You feel nothing. Cholesterol is silent.", "range": "DESIRABLE: 150-200 mg/dL\nHIGH: 240+\nBut can be misleading if high HDL drives it up (actually good).", "fast": "YES. Fast 8-12hr.", "retest": "6-12 months", "one": "STOP looking at total cholesterol alone. It is the least useful lipid number. ApoB tells you 10x more."}, {"n": "LDL Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "LDL particles carry cholesterol and burrow into artery walls building plaque — like rust inside a pipe. LDL-C measures the WEIGHT of cholesterol, not the NUMBER of particles. ApoB (particle count) is more accurate.", "feel": "Nothing for decades. By the time you feel it (chest pain), plaque is significant.", "range": "OPTIMAL: below 100\nLONGEVITY: below 70\nHIGH: above 130", "fast": "YES. Fast 8-12hr.", "retest": "6-12 months", "one": "LDL is important but ApoB is more important. If you can only obsess over one, choose ApoB."}, {"n": "HDL Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "HDL is the cleanup crew — picks up excess cholesterol from artery walls and returns it to liver for disposal. LDL = delivery trucks dropping off cholesterol everywhere. HDL = garbage trucks cleaning it up. More garbage trucks = better.", "feel": "Nothing directly. But low HDL = less cleanup = more plaque silently building.", "range": "OPTIMAL: above 60 mg/dL\nLOW (risky): below 40\nWomen naturally higher than men.", "fast": "YES. Fast 8-12hr.", "retest": "6-12 months", "one": "No drug effectively raises HDL. Exercise is the only proven booster."}, {"n": "Triglycerides", "cat": "HEART & CHOLESTEROL", "what": "Actual FAT molecules in your blood. When you eat more than you need (especially sugar/carbs), liver converts excess into triglycerides and ships them for storage. It is the overflow from your kitchen trash being bagged up.", "feel": "Nothing directly. Very high (>500) can cause pancreatitis.", "range": "OPTIMAL: below 75\nGOOD: 75-100\nHIGH: 150+\nDANGEROUS: 500+ (pancreatitis risk)", "fast": "YES. Fast 8-12hr.", "retest": "6-12 months", "one": "TG ÷ HDL ratio: below 1.0 = excellent insulin sensitivity. Above 2.0 = likely insulin resistant. Free calculation, surprisingly predictive."}, {"n": "ApoA-1", "cat": "HEART & CHOLESTEROL", "what": "Protein on HDL (cleanup crew) particles. ApoB:ApoA ratio = balance between particles building plaque vs cleaning it up.", "feel": "Nothing. Risk assessment marker.", "range": "GOOD: above 150 mg/dL\nApoB:ApoA ratio:\nLOW RISK: below 0.6\nHIGH RISK: above 0.8", "fast": "YES. Fast.", "retest": "6-12 months", "one": "After H+ results: divide ApoB by ApoA-1. Below 0.6 = cardiovascularly solid."}, {"n": "Hemoglobin", "cat": "BLOOD CELLS", "what": "Protein in red blood cells that grabs oxygen from lungs and delivers to every cell. Like a fleet of oxygen delivery trucks. Fewer trucks = cells starve for oxygen = you feel exhausted.", "feel": "LOW (anemia): tired all the time, pale eyelids (check mirror — should be bright red, pale pink = anemic), breathless during exercise, dizzy, cold hands/feet, heart pounding during minor effort.\nHIGH: usually dehydration.", "range": "WOMEN: 12.5-15.0 g/dL\nANEMIC: below 12.0\nBelow 11 = moderate anemia, urgent.", "fast": "No.", "retest": "6 months", "one": "Pull down your lower eyelid in a mirror. Bright red = good. Pale pink = possibly anemic. Crude but useful quick check."}, {"n": "WBC + Differential", "cat": "BLOOD CELLS", "what": "Your immune army. Different soldier types fight different threats:\n\nNEUTROPHILS (60%): infantry — rush to bacteria\nLYMPHOCYTES (30%): special forces — fight viruses, cancer\nMONOCYTES (6%): cleanup crew\nEOSINOPHILS (3%): parasite fighters (relevant in Bali!)\nBASOPHILS (1%): allergy mediators", "feel": "Pattern tells the story:\nHigh neutrophils + fever = bacterial infection\nHigh lymphocytes = viral infection\nHigh eosinophils = PARASITES (common in Bali!) or allergies\nLow lymphocytes = immune suppression", "range": "WBC: 4.5-8.0 K/μL\nNeutrophils: 2-7\nLymphocytes: 1-3.5\nEosinophils: 0-0.5", "fast": "No.", "retest": "6 months", "one": "EOSINOPHILS elevated in Bali = check for parasites (stool PCR). Tropical living = higher parasite exposure. Many people carry parasites with zero symptoms."}, {"n": "Platelets + ESR + NLR", "cat": "BLOOD CELLS", "what": "PLATELETS: biological band-aids. Too few = bleed easily. Too many = clot risk.\nESR: old-school inflammation marker (how fast red cells settle in tube). Non-specific.\nNLR: neutrophils ÷ lymphocytes ratio = cheap inflammation/immune stress score hiding in your CBC.", "feel": "Low platelets: easy bruising, bleeding gums, tiny red dots on skin.\nHigh ESR/NLR: you might not feel it, but body is in chronic inflammatory/stress state.", "range": "Platelets: 150-400 K/μL\nESR women: below 15\nNLR: 1.0-2.0 optimal, above 3.0 = investigate", "fast": "No.", "retest": "6 months", "one": "After CBC results: neutrophil count ÷ lymphocyte count. Above 3.0 = chronic immune stress. Combine with hs-CRP for the full inflammation picture."}, {"n": "AST (SGOT)", "cat": "LIVER", "what": "Similar to ALT but found in liver AND muscle AND heart. So elevated AST could mean liver damage OR just a hard workout. Doctors look at AST + ALT together to figure out WHERE damage is.", "feel": "Nothing. Liver suffers silently.", "range": "OPTIMAL: below 25 U/L\nKey: Both elevated = probably liver. AST high + ALT normal = probably muscle from exercise.", "fast": "No.", "retest": "3-6 months", "one": "If AST high + ALT normal: check CK (muscle enzyme). If CK also high, the AST is from training, NOT your liver."}, {"n": "GGT + ALP + Bilirubin + Albumin + Protein + CHE", "cat": "LIVER", "what": "SUPPORTING LIVER MARKERS:\nGGT: Canary in coal mine — rises first with alcohol, even moderate. Most sensitive.\nALP: Liver OR bone (check GGT to determine which).\nBilirubin: Yellow pigment from RBC breakdown. Mild elevation often harmless (Gilberts).\nAlbumin: Main blood protein. Reflects nutrition + liver production.\nTotal Protein: Albumin + immune proteins. A:G ratio below 1.0 = investigate.\nCHE: Liver PRODUCTION capacity (vs ALT/AST which measure DAMAGE).", "feel": "GGT up: usually alcohol or meds (no symptoms).\nBilirubin up: yellowing eyes/skin if significant.\nAlbumin down: swelling in feet/ankles, poor wound healing.\nCHE down: liver production failing (serious).", "range": "GGT: below 15 optimal\nALP: 44-147\nBilirubin: 0.1-1.0\nAlbumin: 4.0-5.0\nA:G ratio: above 1.0\nCHE: 5300-12900", "fast": "No.", "retest": "6 months", "one": "GGT elevated + normal AST/ALT = early warning. Mild bilirubin elevation + everything normal = Gilberts (benign, possibly protective). Albumin dropping on reta = not eating enough protein."}, {"n": "Creatinine + eGFR", "cat": "KIDNEY", "what": "Waste from muscle creatine metabolism. Kidneys filter it. eGFR = calculated kidney filtration %.\n\nYOUR ISSUE: 10g daily creatine artificially raises creatinine and falsely lowers eGFR. Your kidneys may be fine while the test looks alarming.", "feel": "Nothing from mild impairment. By the time you feel kidney symptoms (swelling, foamy urine), significant damage occurred.", "range": "Creatinine: 0.5-0.9\neGFR: above 90\n\nBUT your creatine supp = expect creat ~1.0-1.5 and eGFR ~60-80. NOT kidney disease.", "fast": "No.", "retest": "6 months", "one": "TELL the lab/doctor you take 10g creatine BEFORE they interpret. Without this context, they may diagnose kidney disease that does not exist."}, {"n": "BUN", "cat": "KIDNEY", "what": "Waste from protein breakdown. Kidneys filter it out. Like checking how full your trash bin is — either making too much trash (high protein diet) or garbage truck not coming (kidneys struggling).", "feel": "Usually nothing unless very high.", "range": "NORMAL: 7-18\nBUN:Creat ratio above 20:1 = dehydration\nBelow 10:1 = liver disease", "fast": "YES.", "retest": "6 months", "one": "BUN ÷ Creatinine ratio above 20 = probably dehydrated. Hydrate and retest."}, {"n": "Calcium + Phosphate", "cat": "KIDNEY", "what": "CALCIUM: 99% in bones, but the 1% in blood is critical for heart rhythm, muscle contraction, nerve signals. Body mines skeleton if blood calcium drops.\nPHOSPHATE: Works with calcium for bones and energy (ATP). They seesaw — one up, other tends down.", "feel": "HIGH Ca: thirst, frequent urination, constipation, kidney stones.\nLOW Ca: cramps, tingling fingers/lips, irregular heartbeat.\nPhosphate: usually asymptomatic.", "range": "Ca: 8.5-10.2\nPO4: 2.5-4.5\n\nAlways interpret Ca with albumin (low albumin = falsely low Ca).", "fast": "No.", "retest": "6 months", "one": "D3+K2 together is important. Without K2, high-dose D3 can push calcium into arteries instead of bones."}, {"n": "Estradiol (E2)", "cat": "HORMONES", "what": "Primary estrogen. WAY more than reproduction: bone density, brain, skin collagen, cardiovascular protection, joints, mood. Fluctuates with menstrual cycle — number only means something if you know cycle day.", "feel": "LOW: irregular/missing periods, hot flashes, dry skin/vagina, joint pain, brain fog, bone loss, insomnia.\nHIGH (vs progesterone): heavy periods, breast tenderness, bloating, headaches, anxiety.", "range": "Follicular (Day 1-13): 30-120\nOvulatory (Day 14): 100-400\nLuteal (Day 15-28): 50-250\n\nMUST record cycle day.", "fast": "No. Record\ncycle day.", "retest": "3-6 months", "one": "Period becoming irregular on reta = check E2 + LH/FSH. Period loss on caloric deficit is your loudest warning signal."}, {"n": "Progesterone", "cat": "HORMONES", "what": "Estrogen is calming counterpart. If estrogen = gas pedal, progesterone = brake. Promotes deep sleep (acts on GABA receptors like sleep meds), calm mood, cycle regularity. Produced AFTER ovulation (Days 15-28).", "feel": "LOW: PMS, anxiety before period, trouble sleeping in 2nd half of cycle, spotting before period, short luteal phase, heavy periods. These are SO common women think they are \"normal.\" They are often fixable.", "range": "Luteal (Day 21): 5-20 ng/mL\nFollicular: below 1 (normal)\n\nMUST test Day 21 or 7 days post-ovulation.", "fast": "No. Test Day 21.", "retest": "3-6 months", "one": "Have PMS? Anxiety before period? Poor sleep luteal phase? Low progesterone is the most likely cause. Vitex is the most evidence-based natural fix."}, {"n": "FSH + LH", "cat": "HORMONES", "what": "Brain signals to ovaries.\nFSH: \"Start growing an egg.\"\nLH: \"OVULATE NOW!\"\n\nLH:FSH above 2:1 = classic PCOS\nFSH above 10 at age 30 = declining reserve (check AMH)\nBoth very low = brain turned off reproduction (hypothalamic amenorrhea from undereating)", "feel": "High FSH: perimenopause approaching.\nHigh LH/FSH ratio: PCOS — irregular periods, acne, excess hair, insulin resistance.\nBoth low: periods stop because brain says \"not safe to reproduce\" (undereating).", "range": "FSH Day 3: 3-10\nLH Day 3: 2-10\nLH:FSH ratio: ideally ~1:1", "fast": "No. Test Day 3.", "retest": "Annually or\nif periods change", "one": "LH:FSH above 2:1 + insulin resistance = classic PCOS that reta may actually treat via the insulin pathway."}, {"n": "Free + Total Testosterone + SHBG", "cat": "HORMONES", "what": "Testosterone is not just for men. Women need it for energy, libido, muscle, bone, confidence, cognition.\nTotal T = all (bound+free). Free T = the 1-3% actually available to work.\nSHBG = handcuffs for sex hormones. High SHBG = more T handcuffed = functionally low T even if total looks normal.\nOral contraceptives massively raise SHBG → bind up free T → explains low libido on the pill.", "feel": "LOW free T: fatigue, low motivation, zero libido, cant build muscle, flat mood.\nHIGH free T: acne (jawline/chin), excess facial/body hair, hair thinning on head, irregular periods. Often PCOS.", "range": "Total T: 15-70 ng/dL\nFree T: 0.5-2.5 pg/mL\nSHBG: 40-120 nmol/L\n\nInterpret together. Same total T = different symptoms depending on SHBG.", "fast": "No. Morning\n8-10am.", "retest": "6 months", "one": "On the pill with zero libido? Your OCP raises SHBG so high that free testosterone is near zero. Extremely common, almost never discussed. Check free T and SHBG."}, {"n": "DHEA-S + Prolactin", "cat": "HORMONES", "what": "DHEA-S: most abundant hormone, made by adrenals. Precursor to testosterone + estrogen. Peaks at 25, declines ~2%/year. The \"youth hormone.\"\n\nPROLACTIN: pituitary hormone. Elevated = irregular periods, low libido. #1 cause of mild elevation? STRESS (including the stress of the blood draw itself).", "feel": "Low DHEA-S: fatigue, low libido, accelerated aging appearance.\nHigh Prolactin: irregular/absent periods, nipple discharge, low libido.\n\nMild prolactin elevation from stress is very common and NOT concerning.", "range": "DHEA-S age 30: 150-350 μg/dL\nProlactin: below 25 ng/mL\n\nProlactin 25-50: likely stress, retest.\n100+: likely prolactinoma (usually benign).", "fast": "No. Morning.\nMinimize stress\nfor prolactin.", "retest": "6 months", "one": "If prolactin mildly elevated: do NOT panic. Retest 2-4 weeks later, well-rested, relaxed. The blood draw stress itself can raise it."}, {"n": "Iron Panel (SI + TIBC + Transferrin)", "cat": "IRON", "what": "Think of iron transport like a bus system:\nSERUM IRON: passengers (iron) on buses right now\nTRANSFERRIN: the buses (transport protein)\nTIBC: total seats available on all buses\nUIBC: empty seats remaining\n\nIron DEFICIENT → body makes MORE buses (high TIBC) trying to grab every scrap. Like adding extra routes during rush hour.\nIron OVERLOADED → fewer empty seats (low TIBC) because all buses full.", "feel": "DEFICIENCY pattern (high TIBC + low iron + low ferritin): fatigue, pale skin, hair loss, brittle nails, cold intolerance, poor exercise performance, restless legs.\nOVERLOAD pattern (low TIBC + high iron + high ferritin): joint pain, fatigue, darkening skin.", "range": "Serum Iron: 60-170\nTIBC: 250-370\nTransferrin: 200-360\n\nTransferrin Saturation (iron÷TIBC×100):\nBelow 20% = deficiency\nAbove 45% = overload", "fast": "YES. Morning\n(iron fluctuates\nthrough day).", "retest": "3-6 months", "one": "Calculate transferrin saturation: Iron ÷ TIBC × 100. Below 20% = need iron. Above 45% = too much. Single most useful iron calculation."}, {"n": "Vitamin D (25-OH)", "cat": "VITAMINS", "what": "Not a vitamin — a HORMONE your body makes when sunlight hits skin. Every cell has D receptors. Regulates immune function, bone density, mood, cancer prevention, muscle function, inflammation.\n\nDespite Bali sun, many are deficient: sunscreen blocks 95% of D production, indoor lifestyle, darker skin produces D slower.", "feel": "DEFICIENCY: fatigue, getting sick often, depression, bone/muscle pain, slow wound healing, hair loss.\nSevere: weak bones (osteomalacia).", "range": "OPTIMAL: 40-60 ng/mL\nADEQUATE: 30-40\nINSUFFICIENT: 20-30\nDEFICIENT: below 20", "fast": "No.", "retest": "6 months", "one": "Living in Bali ≠ adequate D. If indoors during peak sun, using sunscreen, or training inside — supplement regardless of location."}, {"n": "Folic Acid (B9)", "cat": "VITAMINS", "what": "Essential for DNA synthesis, red blood cells, methylation (detox/hormone processing). Synthetic form = \"folic acid.\" Natural = \"folate.\"\n\nKEY: ~40% of people have MTHFR gene variant impairing folic acid → active folate conversion. If you are one: regular folic acid supplements do not work. Need \"methylfolate\" (L-5-MTHF).", "feel": "DEFICIENCY: fatigue, brain fog, mouth sores, elevated homocysteine (CV risk), anemia.", "range": "OPTIMAL: above 15 ng/mL\nDEFICIENT: below 3", "fast": "No.", "retest": "6 months", "one": "If homocysteine is high: folate + B12 are most likely causes. Use methylated forms (methylfolate + methylcobalamin)."}, {"n": "Zinc + Selenium + RBC Magnesium + Copper", "cat": "VITAMINS", "what": "The thyroid mineral quartet:\nZINC: 100+ enzymes, immune, skin, T4→T3 conversion. No storage — need daily.\nSELENIUM: Thyroid conversion, antioxidant. 200mcg/day proven to lower Anti-TPO 40-60%. 2 Brazil nuts = enough.\nRBC MAGNESIUM: Accurate intracellular Mg (serum Mg is poor marker). 300+ reactions.\nCOPPER: Balance with zinc. Excess = anxiety, insomnia. If supplementing zinc, check copper.", "feel": "ZINC low: frequent colds, poor healing, acne, hair loss, lost taste/smell, white nail spots.\nSELENIUM low: poor thyroid, weak immunity.\nMg low: cramps, poor sleep, anxiety, palpitations, migraines, eye twitching.\nCOPPER excess: anxiety, insomnia, racing mind.", "range": "Zinc: 70-100 μg/dL\nSelenium: 70-150 ng/mL\nRBC Mg: 4.2-6.8 mg/dL\nCopper: 80-155 μg/dL", "fast": "YES morning\n(zinc, selenium)", "retest": "6 months\n(Se: annually)", "one": "Mg glycinate 400mg nightly = cheapest intervention for sleep + cramps + anxiety. 2 Brazil nuts daily = cheapest thyroid support. If supplementing zinc: monitor copper after 3 months."}, {"n": "Hepatitis B + C + HIV", "cat": "INFECTIOUS", "what": "HBsAg: Are you currently infected with Hep B?\nAnti-HBs: Are you immune to Hep B (from vaccine)?\nAnti-HCV: Have you been exposed to Hep C? (Now CURABLE >95%)\nHIV Ab/Ag: 4th gen test detecting both antibodies and antigen.\n\nAll one-time baseline screening. SE Asia has higher hepatitis prevalence than Western countries.", "feel": "Hep B/C: often NO symptoms for years while liver is silently damaged.\nHIV acute: flu-like illness 2-6 weeks after infection.\nAll three: manageable/curable with modern treatment.", "range": "ALL: NEGATIVE\n\nAnti-HBs: POSITIVE above 10 = immune from vaccine (good)\nAnti-HBs below 10 = need booster", "fast": "No.", "retest": "One-time", "one": "Hep C is curable. HIV is manageable. Neither is a death sentence anymore. Testing is routine health maintenance."}, {"n": "H. Pylori", "cat": "INFECTIOUS", "what": "Corkscrew bacteria that burrows into stomach lining. ~50% of world carries it, higher in SE Asia/Indonesia. Most have NO symptoms. But in some: gastritis, ulcers, and significantly increased gastric cancer risk.\n\nJapan screens everyone because stomach cancer is common there. Breath test is most accurate non-invasive method.", "feel": "MOST: no symptoms at all.\nSOME: burning stomach pain, bloating, nausea, acid reflux, loss of appetite. These = gastritis or ulcers from H. pylori.", "range": "NEGATIVE\n\nIf positive + symptomatic: treat.\nIf positive + asymptomatic: usually treat to reduce long-term cancer risk.", "fast": "YES for\nbreath test.", "retest": "Once. Retest\nafter treatment.", "one": ">50% of SE Asian population positive. Modifiable risk factor for stomach cancer. Breath test is quick, cheap, accurate."}, {"n": "CA-125 + CEA + AFP", "cat": "CANCER MARKERS", "what": "CA-125: Ovarian marker. Also elevated in endometriosis, fibroids, menstruation (high false positive rate).\nCEA: Colorectal/GI marker. Also elevated in smokers.\nAFP: Liver cancer marker. Most relevant if hepatitis positive.\n\nPSA (in H+ panel): Prostate marker. NO validated use in women. H+ including it in a women panel is a design error — flag it to them.", "feel": "You feel nothing from tumor markers. They are screening tools. Symptoms come from the underlying condition if present.", "range": "CA-125: below 35 U/mL\nCEA: below 3.0 (non-smoker)\nAFP: below 10 ng/mL\n\nElevated ≠ cancer. Most elevations are benign. But warrant investigation.", "fast": "No.\nCA-125: avoid\ntesting during\nperiod.", "retest": "Annually", "one": "CA-125 during your period = falsely elevated = unnecessary anxiety. Test mid-cycle. PSA in a women panel is a copy-paste error — mention it to H+."}, {"n": "DEXA Scan", "cat": "BODY SCANS", "what": "Gold standard for BOTH bone density AND body composition. Uses two low-energy X-rays to measure bone, fat %, lean mass, visceral fat, and regional distribution — left vs right, trunk vs legs, belly vs hips.\n\nFor reta: answers THE critical question — are you losing FAT or MUSCLE? A scale cannot tell you. DEXA can.", "feel": "You cannot feel bone density loss until a fracture. Body comp itself = no symptoms, but the DATA drives decisions.", "range": "BONE: T-score above -1.0\nBODY FAT women: 20-30% healthy\nBelow 18% = hormonal risk\nAbove 32% = health risk", "fast": "No.", "retest": "6-12 months", "one": "Takes 10 minutes, low radiation. Reveals visceral fat you cannot see. Worth more than any blood test for understanding your body composition on reta."}, {"n": "VO2 Max", "cat": "BODY SCANS", "what": "Maximum oxygen your body can use during intense exercise. THE #1 strongest predictor of how long you will live. Stronger than blood pressure, cholesterol, smoking, or diabetes.\n\nTop quartile VO2 max = 5x lower mortality than bottom quartile.", "feel": "You experience it every workout. Breathless on stairs = low. Sustained intense cardio = high.", "range": "WOMEN age 30:\nPoor: below 28\nGood: 35-40\nExcellent: 40-46\nEvery 1 mL/kg/min = ~2% lower mortality.", "fast": "No big meal\n2hr before.", "retest": "Annually", "one": "Your current training builds strength and muscle. For LONGEVITY, Zone 2 cardio is the missing piece. 3-4 hours/week may add more healthy years than any peptide."}, {"n": "ECG + CAC Score", "cat": "BODY SCANS", "what": "ECG: Heart electrical activity snapshot. 30 seconds. Catches arrhythmias, conduction problems.\nCAC: CT scan of heart plaque. 10 seconds. Score 0 = ZERO plaque = enormous reassurance. Most concrete heart attack predictor.\n\nBoth are quick, cheap, painless baseline tests.", "feel": "ECG findings might explain: palpitations, dizziness, chest discomfort.\nCAC: you feel nothing from plaque until a heart attack. That is the point — find it before symptoms.", "range": "ECG: Normal sinus rhythm\nCAC Score 0: no plaque (ideal)\n1-100: mild\n100-400: significant\n400+: extensive", "fast": "No.", "retest": "ECG: baseline\nthen every 5yr\nCAC: once at 30,\nthen every 5yr", "one": "ECG is Rp 50-150K in Bali. Do it. CAC costs $50-200 in Bangkok. A CAC score of 0 at 30 is the single most reassuring cardiac data you can get."}, {"n": "23andMe + Genetic Panel", "cat": "DNA & GENETICS", "what": "Reads your DNA for variants affecting health risks, nutrient needs, drug metabolism. Results are PERMANENT — test once, valid for life.\n\nBRCA1/2: 5-10x breast/ovarian cancer risk\nMTHFR: B vitamin processing (40% of people have variant)\nApoE4: Alzheimer risk (3-12x)\nCOMT: stress/caffeine processing\nCYP: how you metabolize drugs", "feel": "You do not feel variants. They are predispositions. But KNOWING them changes prevention dramatically.\nBRCA+ = enhanced screening. MTHFR+ = methylated B vitamins only. ApoE4 = aggressive CV prevention.", "range": "Yes/no for each variant. Not a spectrum.", "fast": "No. Saliva\nsample at home.", "retest": "ONCE in your\nentire life.", "one": "23andMe (~$100) → upload to SelfDecode (~$30) = $130 total for lifetime health intelligence affecting every medical decision going forward."}, {"n": "Biological Age Test", "cat": "DNA & GENETICS", "what": "DNA methylation patterns reveal biological vs chronological age. The ultimate benchmark: is your protocol WORKING at the cellular level?\n\nAll your peptides, supplements, exercise, and diet are trying to slow aging. This test measures if they are succeeding.", "feel": "You do not feel biological age. But the test answers: are you aging faster or slower than your calendar age?", "range": "IDEAL: bio age < chrono age\nEven 2-3 years younger = significant\n5+ years younger = excellent", "fast": "No.", "retest": "6-12 months", "one": "TruDiagnostic TruAge ~$300-500. The test Bryan Johnson uses. Do once for baseline, repeat in 6-12 months to measure your protocol is actual effect on cellular aging."}, {"n": "GI-MAP (Stool PCR)", "cat": "GUT HEALTH", "what": "Maps your entire gut ecosystem via DNA analysis:\n- Pathogenic bacteria, parasites (RELEVANT in Bali), candida/yeast\n- Beneficial bacteria levels\n- Gut inflammation (calprotectin = CRP but for your gut)\n- Digestion quality (elastase = pancreatic function)\n- Immune markers (secretory IgA)\n\n70% of your immune system lives in your gut. Gut problems affect EVERYTHING.", "feel": "Bloating, gas, irregular bowels, food sensitivities, brain fog after eating, skin issues (acne, eczema — often gut-related), fatigue, autoimmune symptoms, frequent illness.", "range": "Varies by organism. Lab provides detailed report showing what is in your gut and whether levels are normal/abnormal.", "fast": "N/A.\nHome stool\ncollection.", "retest": "Once, or if\nGI symptoms.", "one": "Chronic bloating, skin issues, or fatigue that blood work cannot explain? The answer might be in your gut."}, {"n": "Pap Smear + HPV", "cat": "WOMEN-SPECIFIC", "what": "Cervical cancer screening. Pap collects cervical cells for precancerous changes. HPV checks for the virus that causes virtually ALL cervical cancers.\n\nOne of the most PREVENTABLE cancers: we know the cause (HPV), can detect early (Pap), can vaccinate (HPV vaccine), and can treat precancerous cells before they become cancer.", "feel": "Early cervical cancer has NO symptoms. By the time you notice (abnormal bleeding, pelvic pain), it is more advanced. The whole point is catching changes BEFORE cancer develops.", "range": "NORMAL PAP + HPV NEGATIVE = low risk for next 3-5 years.\nAbnormal Pap ≠ cancer. Most minor changes resolve on their own.", "fast": "N/A. Avoid\nduring period.", "retest": "1-3 years", "one": "If you have not had a Pap recently, schedule one. Basic preventive care DUE for a 30-year-old woman. Also ask about HPV vaccination if not vaccinated."}, {"n": "Breast + Pelvic Ultrasound", "cat": "WOMEN-SPECIFIC", "what": "BREAST US: Sound waves (no radiation) checking for lumps, cysts, abnormalities. Preferred under 40 (denser tissue makes mammograms less effective).\nPELVIC US: Examines uterus + ovaries for cysts, fibroids, polyps, endometriosis. Can be abdominal (needs full bladder) or transvaginal (more detailed).", "feel": "Most findings are discovered on screening, not from symptoms.\nBreast: new lump, nipple discharge, skin changes.\nPelvic: heavy/painful periods, pelvic pain, bloating.", "range": "BREAST: BIRADS 1-2 = normal.\nBIRADS 3 = probably benign, follow-up 6 months.\nBIRADS 4-5 = biopsy needed.\nPELVIC: normal anatomy, no masses.", "fast": "Pelvic (abdominal):\nfull bladder.", "retest": "Breast: annually\nfrom 30.\nPelvic: every\n2-3 years.", "one": "Baseline at 30 gives future comparison images. If anything changes, doctors compare to baseline. Quick, painless, no radiation."}, {"n": "Cycle Tracking (BBT + Apps)", "cat": "WOMEN-SPECIFIC", "what": "Not a lab test — a daily practice. Track basal body temperature + cervical mucus to identify:\n1. WHETHER you ovulate (temp rises ~0.3°C after and stays up until period)\n2. WHEN you ovulate\n3. Luteal phase length (should be 12-14 days)\n4. Overall regularity\n\nMore powerful than it sounds: reveals progesterone production, thyroid function (low temps = possible hypothyroid), reproductive health — all for FREE.", "feel": "No temp rise = not ovulating. Short luteal (<10 days) = low progesterone. Low temps (<36.1°C) = possible hypothyroid. Cycles irregular on reta = body under too much caloric stress.", "range": "NORMAL CYCLE: 25-35 days\nTEMP SHIFT: 0.3-0.5°C after ovulation\nLUTEAL: 12-14 days", "fast": "N/A.\nTemp immediately\non waking before\nmoving.", "retest": "Daily", "one": "Buy a basal thermometer or Tempdrop wearable. Track 3 months for baseline. This + H+ blood work = complete hormonal picture no single test provides alone."}, {"n": "Skin Check + Eye Exam + Dental", "cat": "PREVENTIVE", "what": "SKIN CHECK: Dermatologist examines every mole with magnified lens. Tropical high-UV Bali = elevated melanoma risk. Melanoma caught early = ~100% survival. Caught late = devastating.\n\nEYE EXAM: Measures pressure (glaucoma), retinal imaging (can detect diabetes/hypertension BEFORE other symptoms), vision.\n\nDENTAL: Oral health linked to cardiovascular disease. Gum disease = chronic inflammation source entering bloodstream. Bleeding gums are NOT normal.", "feel": "SKIN: painless. Visual exam only. ABCDE rule for moles: Asymmetry, Border, Color, Diameter, Evolution.\nEYES: glaucoma steals vision silently. Retinal changes show systemic disease.\nDENTAL: bleeding gums = active infection. Not \"normal.\"", "range": "No suspicious lesions.\nNormal eye pressure + healthy retina.\nNo cavities, healthy gums.", "fast": "N/A.", "retest": "ALL ANNUALLY", "one": "Living in Bali = annual skin check non-negotiable. Bleeding gums = inflammation source nobody checks. Retinal photo = cheapest window into cardiovascular health."}, {"n": "Total Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "The grand total of ALL cholesterol in your blood — HDL + LDL + other types added together. It is the least useful number on your lipid panel but the one doctors quote most often because it is simple.\n\nCholesterol itself is not evil. Your body MAKES it on purpose — it builds cell membranes, produces hormones (estrogen, testosterone, cortisol, vitamin D), and makes bile to digest fat. The question is not \"do I have cholesterol\" but \"are the particles carrying it the dangerous kind?\"", "feel": "You feel nothing from high or low cholesterol directly. Cardiovascular damage builds silently over decades.", "range": "GENERAL GUIDE: 150-200 mg/dL\nBut this number is MISLEADING without context. Someone with total cholesterol 220 driven by very high HDL is healthier than someone at 190 with terrible particle distribution.\n\nLook at ApoB instead.", "fast": "YES. Fast\n8-12 hours.", "retest": "Every 6-12\nmonths", "one": "Total cholesterol is the number everyone knows and the number that matters least. It is like knowing total calories without knowing if they came from vegetables or candy. Focus on ApoB."}, {"n": "LDL Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "LDL stands for Low-Density Lipoprotein. These are particles that carry cholesterol FROM your liver TO your tissues. When there are too many, they get stuck in artery walls and start building plaque.\n\nThink of LDL particles as delivery trucks. They are supposed to deliver cholesterol to cells that need it. But when there are too many trucks on the road, they crash into artery walls and pile up. Over decades, this pileup narrows your arteries.\n\nImportant: LDL-C (what your lab reports) measures the WEIGHT of cholesterol on those trucks. ApoB counts the NUMBER of trucks. Same weight can mean few big trucks (less dangerous) or many small trucks (more dangerous).", "feel": "Nothing. Completely silent. The plaque builds for 20-30 years before causing a heart attack or stroke. By the time you feel something, it is advanced.", "range": "OPTIMAL: below 100 mg/dL\nLOW RISK: below 70 (longevity target)\nBORDERLINE: 100-129\nHIGH: 130-159\nVERY HIGH: 160+", "fast": "YES. Fast.", "retest": "Every 6-12\nmonths", "one": "LDL below 100 is the standard target. Below 70 is the longevity medicine target. If your Lp(a) comes back high, you want LDL even lower to compensate."}, {"n": "HDL Cholesterol", "cat": "HEART & CHOLESTEROL", "what": "HDL stands for High-Density Lipoprotein. These are the CLEANUP particles. They travel around your arteries, pick up excess cholesterol from artery walls, and carry it back to the liver for disposal.\n\nThink of HDL as garbage trucks cleaning up the mess that LDL delivery trucks left behind. More cleanup trucks = cleaner arteries.", "feel": "You do not feel HDL levels directly. But low HDL over decades means less cleanup happening in your arteries.", "range": "OPTIMAL: above 60 mg/dL\nGOOD: 50-60\nLOW (risky): below 40\n\nWomen naturally have higher HDL than men. Below 50 in women is concerning.", "fast": "YES. Fast.", "retest": "Every 6-12\nmonths", "one": "Exercise raises HDL more than any drug, supplement, or diet change. If your HDL is low, the prescription is cardio — zone 2 training 4+ hours per week."}, {"n": "Triglycerides", "cat": "HEART & CHOLESTEROL", "what": "Triglycerides are fat molecules floating in your blood. When you eat more calories than your body needs (especially from sugar and carbs), your liver converts the excess into triglycerides and sends them into your bloodstream for storage.\n\nThink of triglycerides as your body packaging excess energy for later. High triglycerides = your body is consistently dealing with more energy (food) than it can use.\n\nHigh triglycerides are one of the strongest signals of metabolic dysfunction and insulin resistance.", "feel": "Mildly high: nothing. Very high (above 500): can cause PANCREATITIS (dangerous inflammation of the pancreas) — same thing you are monitoring for with reta.", "range": "OPTIMAL: below 75 mg/dL\nGOOD: 75-100\nBORDERLINE: 100-150\nHIGH: 150-500\nDANGEROUS: above 500 (pancreatitis risk)\n\nLab says below 150 is \"normal\" but optimal is below 75.", "fast": "YES. Fast 8-12hr.\nAlcohol 48hr before\nwill spike TG.", "retest": "Every 6-12\nmonths", "one": "The TG/HDL ratio is a free calculation from your standard lipid panel that estimates insulin resistance almost as well as HOMA-IR. Calculate it alongside your other results."}, {"n": "ApoA-1", "cat": "HEART & CHOLESTEROL", "what": "ApoA-1 is the protein sitting on HDL (good cholesterol) particles — like ApoB is on LDL (bad cholesterol) particles.\n\nThe ratio of ApoB to ApoA-1 is one of the strongest predictors of cardiovascular risk:\n- ApoB/ApoA ratio below 0.6 = low risk\n- ApoB/ApoA ratio above 0.8 = high risk", "feel": "Nothing directly. This is predictive data, not something you feel.", "range": "GOOD: above 150 mg/dL\nLAB RANGE: 115-220", "fast": "YES. Fast.", "retest": "Every 6-12\nmonths", "one": "Most people skip this but the ApoB:ApoA ratio is the hidden gem of your lipid panel. Both numbers are in H+. Calculate the ratio yourself."}, {"n": "Hemoglobin", "cat": "BLOOD CELLS", "what": "Hemoglobin is the protein inside red blood cells that carries oxygen from your lungs to every cell in your body and carries CO2 waste back. It is what makes blood red.\n\nThink of hemoglobin as tiny oxygen taxis. Low hemoglobin = not enough taxis = your tissues are starving for oxygen.", "feel": "LOW (anemia): Exhausted all the time, pale skin and lips, shortness of breath during exercise (your muscles literally cannot get enough oxygen), dizzy when standing up, cold hands and feet, heart pounding harder than normal to compensate, poor workout performance.\n\nHIGH: Usually dehydration (blood is thicker so hemoglobin is concentrated). Rarely: polycythemia (body making too many red cells).", "range": "OPTIMAL for women: 12.5-15.0 g/dL\nANEMIC: below 12.0\nLAB RANGE: 12.0-16.0", "fast": "No.", "retest": "Every 6 months", "one": "Women are more prone to low hemoglobin because of monthly blood loss from periods. If you feel inexplicably tired and your workouts have gotten harder, check hemoglobin + ferritin before assuming you need more rest."}, {"n": "Hematocrit", "cat": "BLOOD CELLS", "what": "The percentage of your blood that is red blood cells vs liquid (plasma). Think of it like a smoothie — hematocrit tells you the ratio of fruit (cells) to liquid (plasma).\n\nIf you are dehydrated, there is less liquid so the % of cells looks higher. This is the most common reason for \"high\" hematocrit.", "feel": "HIGH: thick blood, headaches, dizziness, flushed face (usually just dehydration)\nLOW: same as anemia symptoms — fatigue, weakness, pale", "range": "OPTIMAL: 36-44%\nLAB RANGE: 36-46%", "fast": "No.", "retest": "Every 6 months", "one": "If your hematocrit comes back \"high,\" drink 2-3 liters of water and retest before worrying. Dehydration is almost always the cause."}, {"n": "White Blood Cells (WBC)", "cat": "BLOOD CELLS", "what": "Your immune army — the total count of all white blood cell types combined. These are the soldiers that fight infection, kill cancer cells, and clean up damaged tissue.\n\nDifferent types do different jobs:\n- Neutrophils: fight bacteria (60% of WBC)\n- Lymphocytes: fight viruses, make antibodies (30%)\n- Monocytes: clean up debris (5%)\n- Eosinophils: fight parasites, involved in allergies (3%)\n- Basophils: allergic reactions (1%)", "feel": "HIGH WBC: your body is fighting something — infection, inflammation, stress, smoking. You might feel sick, feverish, or just \"off.\"\n\nLOW WBC: your immune system is suppressed — more vulnerable to infections. Could be viral (your body used up soldiers fighting a virus), autoimmune, or medication side effect.", "range": "OPTIMAL: 4.5-8.0 K/μL\nHIGH: above 11.0 (infection or inflammation)\nLOW: below 4.0 (immune suppression)\nVERY HIGH: above 30 (leukemia concern)", "fast": "No.", "retest": "Every 6 months", "one": "The DIFFERENTIAL (breakdown of WBC types) is often more useful than the total count. High eosinophils in Bali = check for parasites. High neutrophils + fever = bacterial infection."}, {"n": "Eosinophils", "cat": "BLOOD CELLS", "what": "These are the white blood cells that specialize in fighting PARASITES and mediating allergic reactions. They are a tiny percentage of your total WBC but very telling.\n\nLiving in Bali, this marker is more relevant for you than for someone in a temperate climate. Tropical environments = higher parasite exposure from food, water, soil, swimming.", "feel": "HIGH: could mean parasitic infection (common in Bali — worms, giardia, etc.), allergies (seasonal, food, or environmental), asthma, eczema, drug reactions.\n\nYou might feel: GI symptoms (bloating, irregular bowel movements), skin itchiness, allergy symptoms — or nothing at all while hosting parasites.", "range": "OPTIMAL: 0.0-0.5 K/μL\nELEVATED: above 0.5\nSIGNIFICANTLY HIGH: above 1.5 (strongly suggests parasites or severe allergic condition)", "fast": "No.", "retest": "Every 6 months", "one": "If your eosinophils are elevated, get a stool PCR test before assuming it is allergies. Parasites are extremely common in Bali and most people do not realize they have them. A comprehensive stool test at Prodia costs Rp 300-500K."}, {"n": "Platelets", "cat": "BLOOD CELLS", "what": "Platelets are the smallest blood cells and their job is CLOTTING — they rush to any cut or damage and clump together to stop bleeding. Think of them as the repair crew that patches holes.\n\nToo few platelets = bleeding risk (bruise easily, cuts take long to stop). Too many = clotting risk (blood clots in wrong places).", "feel": "LOW platelets: bruising easily, tiny red dots on skin (petechiae), nosebleeds, bleeding gums, heavy periods, cuts that keep bleeding.\n\nHIGH platelets: usually no symptoms, but increases risk of blood clots (DVT, stroke, PE).", "range": "OPTIMAL: 150-350 K/μL\nLOW: below 150\nCONCERNING LOW: below 100 (bleeding precautions)\nURGENT: below 50 (specialist needed)\nHIGH: above 400", "fast": "No.", "retest": "Every 6 months", "one": "Low platelets + heavy bruising + liver enzyme elevation = investigate liver disease. This pattern is common in chronic alcohol use but can have other causes."}, {"n": "ESR", "cat": "BLOOD CELLS", "what": "ESR stands for Erythrocyte Sedimentation Rate. It measures how fast your red blood cells settle to the bottom of a tube in one hour. When there is inflammation, blood proteins make red cells clump together and sink faster.\n\nIt is a very old, very simple test — literally watching blood settle in a tube. Not precise, but useful as a general inflammation flag alongside hs-CRP.", "feel": "You do not feel ESR itself. It is a tool to detect and monitor inflammation.\n\nElevated ESR + symptoms = helps confirm inflammatory or autoimmune conditions. Elevated ESR + no symptoms = early warning that something is brewing.", "range": "OPTIMAL for women: below 15 mm/hr\nLAB: below 20\nELEVATED: 20-40 (mild inflammation)\nHIGH: above 40 (significant inflammation, investigate)", "fast": "No.", "retest": "Every 6 months", "one": "ESR is slow to change — it rises slowly with chronic conditions and falls slowly after treatment. hs-CRP is faster and more precise. Together they give a more complete inflammation picture."}, {"n": "MCV (Mean Corpuscular Volume)", "cat": "BLOOD CELLS", "what": "MCV measures the average SIZE of your red blood cells. This seemingly boring number is actually a detective tool — it tells doctors what TYPE of anemia you have.\n\nSmall cells (low MCV = microcytic): almost always iron deficiency or thalassemia trait\nNormal cells (normal MCV): chronic disease, early deficiency, or mixed causes\nLarge cells (high MCV = macrocytic): almost always B12 or folate deficiency, or alcohol excess", "feel": "You do not feel MCV directly. But the underlying cause (iron deficiency, B12 deficiency) causes fatigue, weakness, brain fog, etc.", "range": "OPTIMAL: 80-96 fL\nSMALL (microcytic): below 80\nLARGE (macrocytic): above 96", "fast": "No.", "retest": "Every 6 months", "one": "MCV is a pattern-recognition tool:\n- Low MCV + low ferritin = iron deficiency (classic)\n- High MCV + low B12 = B12 deficiency (classic)\n- Normal MCV + low ferritin + low B12 = MIXED deficiency (both iron AND B12 low — MCV looks normal because small and large cancel out)"}, {"n": "NLR (Neutrophil:Lymphocyte Ratio)", "cat": "BLOOD CELLS", "what": "This is a FREE calculation from your CBC that is surprisingly powerful. Divide your neutrophil count by your lymphocyte count.\n\nNLR is increasingly used in research as a marker of systemic inflammation and immune stress. Higher NLR = more inflammation and immune imbalance. Studies link high NLR to cardiovascular disease, cancer outcomes, and mortality.", "feel": "Nothing directly. But a chronically elevated NLR means your body is in a state of low-grade immune activation — fighting something, even if you do not know what.", "range": "OPTIMAL: 1.0-2.0\nNORMAL: below 3.0\nELEVATED: 3.0-5.0 (investigate)\nHIGH: above 5.0 (significant inflammation or infection)", "fast": "No.", "retest": "Every 6 months", "one": "Your H+ CBC includes both neutrophils and lymphocytes. Just divide neutrophils by lymphocytes. It is a free longevity marker hiding inside a test you are already doing."}, {"n": "AST (SGOT)", "cat": "LIVER", "what": "AST is another liver enzyme like ALT, but here is the key difference: AST is found in your liver AND your muscles AND your heart. So when AST is elevated, it could be liver damage OR it could be muscle damage from an intense workout.\n\nIf AST is high but ALT is normal → probably muscle damage (exercise)\nIf BOTH AST and ALT are high → probably liver", "feel": "Same as ALT — you feel nothing from mild elevation. Liver damage is silent.", "range": "OPTIMAL: below 25 U/L\nLAB: 10-40\n\nSame note as ALT: \"normal\" range is too generous. Below 25 is the target.", "fast": "No.", "retest": "Every 3-6 months", "one": "If AST is 45 but ALT is 18, do not panic about your liver. You probably trained hard recently. Check CK (muscle enzyme) to confirm. If CK is also elevated = exercise-induced, not liver."}, {"n": "GGT (Gamma-GT)", "cat": "LIVER", "what": "GGT is the most SENSITIVE liver marker — it is the first to rise when your liver is stressed. It is especially sensitive to alcohol. Even \"moderate\" drinking (1-2 glasses of wine) can elevate GGT.\n\nGGT is also increasingly recognized as an oxidative stress marker — meaning it reflects how much free radical damage your body is dealing with.", "feel": "Nothing from mild elevation. But GGT rising while AST/ALT are still normal = your liver is sending early warning signals that something is irritating it.", "range": "OPTIMAL: below 15 U/L\nLAB: 9-36\nELEVATED: above 36", "fast": "No.", "retest": "Every 6 months", "one": "If you drink even moderately and your GGT is elevated, the alcohol is affecting your liver more than you think. GGT is the truth serum for alcohol impact."}, {"n": "Alkaline Phosphatase (ALP)", "cat": "LIVER", "what": "ALP is an enzyme found in both your LIVER and your BONES. When ALP is elevated, the question is: liver or bone?\n\nThe trick to tell: check GGT.\n- ALP high + GGT high = liver cause (bile duct issue)\n- ALP high + GGT normal = bone cause (fracture healing, Pagets, vitamin D issues)\n\nIn young women, bone causes are less common, so liver is more likely if elevated.", "feel": "Nothing from mild elevation. Significantly elevated (3-4x normal): possible bile duct obstruction — jaundice, itching, dark urine.", "range": "LAB: 44-147 U/L\n(Wide range because both liver and bone contribute)", "fast": "No.", "retest": "Every 6 months", "one": "Simple rule: ALP up + GGT up = liver problem. ALP up + GGT normal = bone problem. The GGT you already have in your H+ panel gives you this context."}, {"n": "Bilirubin", "cat": "LIVER", "what": "Bilirubin is a yellow pigment created when your body breaks down old red blood cells. Your liver processes it and sends it out through bile.\n\nIf bilirubin builds up: your skin and eyes turn YELLOW (jaundice). This is unmistakable — it is one of the few blood markers you can literally see.\n\nFun fact: about 5% of people have Gilberts syndrome — a harmless genetic variant that causes mildly elevated bilirubin. These people may notice slightly yellow eyes when tired or fasting. It is actually PROTECTIVE — bilirubin is an antioxidant.", "feel": "Mildly elevated: usually nothing, especially if Gilberts.\nSignificantly elevated: yellow skin and eyes (jaundice), dark urine, pale stool, itchy skin. This means your liver or bile ducts are in trouble.", "range": "TOTAL: 0.1-1.0 mg/dL\nDIRECT: 0-0.3\n\nAbove 2.0 with symptoms = investigate urgently\n1.0-2.0 with no other liver abnormalities = likely Gilberts (benign)", "fast": "No.", "retest": "Every 6 months", "one": "If your bilirubin is slightly elevated (1.0-2.0) but ALL other liver tests are normal, you probably have Gilberts syndrome. It is benign and actually associated with lower cardiovascular disease risk because bilirubin is an antioxidant."}, {"n": "Albumin", "cat": "LIVER", "what": "Albumin is the most abundant protein in your blood, made entirely by your liver. It does three critical things:\n1. Keeps fluid inside your blood vessels (low albumin = fluid leaks into tissues = swelling)\n2. Carries hormones, medications, and vitamins through your blood\n3. Reflects both liver function and nutritional status\n\nThink of albumin as a measure of how well your liver is producing AND how well you are nourishing your body.", "feel": "LOW: swelling (especially ankles and around eyes), fatigue, muscle wasting, poor wound healing. Very low albumin in hospitalized patients is associated with much worse outcomes from any condition.", "range": "OPTIMAL: 4.0-5.0 g/dL\nLAB: 3.5-5.0\nLOW: below 3.5 (investigate)\nCRITICAL: below 2.5 (serious)", "fast": "No.", "retest": "Every 6 months", "one": "Albumin below 3.5 on reta = you are probably not eating enough protein. Your appetite is suppressed but your protein needs have not changed. Prioritize protein even when you do not feel hungry."}, {"n": "Cholinesterase (CHE)", "cat": "LIVER", "what": "Most people have never heard of this test. CHE measures your livers ability to PRODUCE a specific enzyme. While ALT/AST tell you about liver DAMAGE (cells leaking enzymes), CHE tells you about liver FUNCTION (can it still make things properly?).\n\nThink of it this way:\n- ALT/AST = is the factory on fire? (damage)\n- CHE = is the factory still producing goods? (function)\n\nYou can have a factory that is slightly on fire but still producing. Or one that looks fine from outside but has stopped producing. CHE catches the second scenario.", "feel": "LOW CHE: your liver is failing to produce properly. This is a serious finding. You would feel weak, fatigued, possibly bruising easily (liver also makes clotting factors).\n\nHIGH CHE: obesity, diabetes, metabolic syndrome (liver is overproducing in response to metabolic stress).", "range": "LAB: 5,300-12,900 U/L\nLOW: liver production failure\nHIGH: metabolic syndrome", "fast": "No.", "retest": "Every 6 months", "one": "H+ including CHE is genuinely unusual and valuable. It tells you something ALT/AST cannot — whether your liver is still functionally productive. Most panels only test for damage, not function."}, {"n": "Creatinine + eGFR", "cat": "KIDNEY", "what": "Creatinine is a waste product from muscle metabolism. Your kidneys filter it out of your blood into your urine. If creatinine is building up in your blood, it means your kidneys are not filtering efficiently.\n\neGFR (estimated Glomerular Filtration Rate) is CALCULATED from creatinine — it estimates how many milliliters of blood your kidneys filter per minute. Higher eGFR = better kidney function.\n\nBIG CAVEAT FOR YOU: you take 10g of creatine daily. Creatine breaks down into creatinine. So your creatinine will be ARTIFICIALLY HIGH and your eGFR ARTIFICIALLY LOW — not because your kidneys are failing, but because you are supplementing the precursor. Tell any doctor this.", "feel": "Mild kidney impairment: nothing (kidneys have massive reserve). Moderate: foamy urine, swelling, fatigue. Severe: nausea, confusion, heart rhythm problems.", "range": "CREATININE optimal: 0.5-0.9 mg/dL\neGFR: above 90 = normal\n60-90 = mild decrease\nbelow 60 = moderate (investigate)\nbelow 30 = severe\n\nBUT for you on 10g creatine: expect creatinine to be elevated and eGFR to look lower than reality. THIS IS A FALSE ALARM from creatine supplementation.", "fast": "No.", "retest": "Every 6 months", "one": "DO NOT let a doctor panic you about \"low eGFR\" or \"high creatinine\" without mentioning your 10g daily creatine. This is the #1 source of unnecessary alarm in supplement users. Cystatin C is the accurate kidney test for you."}, {"n": "Cystatin C", "cat": "KIDNEY", "what": "Cystatin C is an alternative kidney function marker that is NOT affected by muscle mass, creatine supplementation, diet, or exercise. It is produced by all cells in your body at a constant rate and filtered only by your kidneys.\n\nFor you specifically — someone who takes 10g creatine daily and trains intensely — this is the ONLY accurate kidney function test. Creatinine-based eGFR will overestimate your kidney impairment because of creatine.", "feel": "Same as creatinine — if truly elevated, your kidneys are not filtering properly. But since cystatin C is not confounded by muscle/creatine, you can trust the result.", "range": "OPTIMAL: 0.53-0.95 mg/L\n\nCystatin C-based eGFR is more accurate than creatinine-based eGFR for athletes and anyone on creatine.", "fast": "No.", "retest": "Annually", "one": "Ask Helix to add this. It probably costs Rp 300-500K. Without it, your kidney function data from H+ is meaningless because creatine makes creatinine unreliable. This is a known limitation that most wellness panels ignore."}, {"n": "BUN (Blood Urea Nitrogen)", "cat": "KIDNEY", "what": "When your body breaks down protein (from food or from your own muscle), it produces nitrogen waste. Your liver converts this into urea, which your kidneys filter out through urine.\n\nBUN measures how much urea waste is in your blood. High BUN can mean: kidneys not filtering well, you are eating a LOT of protein, you are dehydrated, or there is bleeding in your GI tract (blood = protein = more nitrogen).", "feel": "Mild elevation: nothing (usually just dehydration or high protein diet). Severe: nausea, confusion, fatigue — signs of kidney failure.", "range": "OPTIMAL: 7-18 mg/dL\nLAB: 7-20\n\nBUN:Creatinine ratio is useful:\n- Above 20:1 = dehydration\n- Below 10:1 = liver disease", "fast": "YES for accuracy", "retest": "Every 6 months", "one": "A BUN of 22 with a high protein diet is completely different from a BUN of 22 with a normal protein diet. Context matters. Tell the lab about your protein intake."}, {"n": "Uric Acid", "cat": "KIDNEY", "what": "Uric acid is a waste product from breaking down purines — molecules found in certain foods (red meat, organ meats, shellfish, beer) and in your own cells.\n\nNormally your kidneys filter it out. But when uric acid gets too high, it can form sharp CRYSTALS in your joints — this is GOUT, one of the most painful conditions that exists. It can also form kidney stones.\n\nCRITICAL FOR YOU: when you lose body fat rapidly (as on retatrutide), your fat cells release stored purines as they shrink. More purines = more uric acid = higher gout risk. This is a KNOWN side effect of rapid weight loss.", "feel": "GOUT: sudden, excruciating joint pain (usually big toe first, but can hit any joint), joint becomes red, hot, swollen. Often starts at night. The pain is described as feeling like the joint is on fire.\n\nKIDNEY STONES: severe flank pain radiating to groin, blood in urine, nausea.", "range": "OPTIMAL: 2.5-5.5 mg/dL\nLAB: 2.4-6.0\nELEVATED: 6.0-7.0 (gout risk increasing)\nHIGH RISK: above 7.0 (crystal formation likely)", "fast": "YES. Fast.", "retest": "Every 3 months\non reta", "one": "Prevention is simple: drink 3+ liters of water daily on reta. Water is the best uric acid flusher. In Bali, coconut water is even better — hydrating + potassium. If you start getting joint pain on reta, uric acid is the prime suspect."}, {"n": "Free T4", "cat": "THYROID", "what": "T4 is the hormone your thyroid produces in the LARGEST quantity. But T4 itself is INACTIVE — it is a storage form, a precursor. Think of T4 as a raw ingredient that needs to be cooked (converted to T3) before your body can use it.\n\n\"Free\" means unbound — available for conversion. Most T4 in your blood is bound to proteins and unavailable. Free T4 is the portion that can actually be converted to active T3.\n\nYour thyroid makes about 80% T4 and 20% T3. The conversion from T4→T3 happens in your liver, gut, and tissues and requires selenium, zinc, and iron.", "feel": "LOW FT4: hypothyroid symptoms (fatigue, weight gain, cold, brain fog) — but usually T3 is more directly linked to how you feel.\n\nHIGH FT4: hyperthyroid symptoms (anxiety, weight loss, tremor, racing heart).", "range": "OPTIMAL: 1.0-1.5 ng/dL\nLAB: 0.8-1.8", "fast": "No. Morning\npreferred.", "retest": "Every 3 months", "one": "FT4 tells you what your thyroid is PRODUCING. FT3 tells you what your body is USING. If FT4 is normal but FT3 is low, the production is fine but the conversion is broken. Fix conversion with selenium, zinc, and iron."}, {"n": "Thyroglobulin Antibody (TgAb)", "cat": "THYROID", "what": "This is the SECOND thyroid autoimmune marker (the first being Anti-TPO). Thyroglobulin is a protein the thyroid uses to make hormones. When your immune system makes antibodies against thyroglobulin, it is another sign of autoimmune thyroid attack.\n\nTesting BOTH Anti-TPO and TgAb catches over 95% of autoimmune thyroid disease. Some people are positive for one but not the other, so testing both is important.\n\nTgAb is also used to monitor thyroid cancer after treatment (different context, not relevant to you right now).", "feel": "Same as Anti-TPO — you feel nothing in early stages. This is a silent autoimmune process that gradually damages your thyroid over years.", "range": "OPTIMAL: below 4.0 IU/mL\nLAB: below 4.0\n\nAny elevation = autoimmune thyroid activity.", "fast": "No.", "retest": "ONCE.\nAnnually if\npositive.", "one": "H+ includes BOTH thyroid antibodies, which is the complete autoimmune thyroid picture. If both are negative, you can relax about autoimmune thyroid disease. If either is positive, selenium supplementation is your first intervention."}, {"n": "Estradiol (E2)", "cat": "HORMONES", "what": "Estradiol is your primary ESTROGEN — the hormone that makes you biologically female. It controls your menstrual cycle, keeps your bones dense, protects your heart, keeps skin elastic and hydrated, supports brain function and mood, and maintains vaginal health.\n\nEstradiol FLUCTUATES massively throughout your menstrual cycle:\n- Days 1-5 (period): LOW\n- Days 6-13 (follicular): RISING\n- Day 14 (ovulation): PEAK — 3-4x higher than baseline\n- Days 15-28 (luteal): MODERATE then drops\n\nThis means a single estradiol number is MEANINGLESS without knowing what cycle day you tested on.", "feel": "LOW estradiol: irregular or missing periods, vaginal dryness, hot flashes, brain fog, mood swings, bone loss over time, dry skin, low libido, difficulty sleeping. This is what menopause feels like — and what extreme caloric restriction or very low body fat can trigger prematurely.\n\nHIGH estradiol (relative to progesterone): heavy periods, breast tenderness, bloating, PMS, fibroids, weight gain around hips/thighs, anxiety.", "range": "Depends ENTIRELY on cycle day:\nFollicular (Day 3): 30-120 pg/mL\nOvulation peak: 100-400\nLuteal: 50-250\n\nMUST note cycle day.", "fast": "No.\nTest Day 3\nfor baseline.", "retest": "Every 3-6 months", "one": "Write your cycle day on the lab requisition form. Literally write \"Cycle Day ___\" next to the estradiol order. Without this, the result is uninterpretable. Day 3 is the standard baseline day."}, {"n": "Progesterone", "cat": "HORMONES", "what": "Progesterone is estrogens calming counterpart. If estrogen is the gas pedal (growth, stimulation), progesterone is the brake pedal (calming, anti-anxiety, pro-sleep).\n\nProgesterone is mainly produced AFTER ovulation by the corpus luteum (the empty egg follicle). So progesterone is only meaningfully present in the second half of your cycle (luteal phase, Days 15-28).\n\nIf you do not ovulate in a given cycle (anovulation), you produce almost NO progesterone that month. This is common with PCOS, stress, undereating, and extreme exercise.", "feel": "LOW progesterone (or high estrogen relative to progesterone = \"estrogen dominance\"):\nPMS (mood swings, irritability, crying before period), anxiety, insomnia (especially in the luteal phase), heavy periods, spotting before your period starts, difficulty maintaining early pregnancy, breast tenderness.\n\nProgesterone is the \"chill hormone.\" Without it, you feel wired and anxious in the second half of your cycle.", "range": "LUTEAL PHASE (Day 21): 5-20 ng/mL\nFOLLICULAR (Day 3): below 1 (normal — progesterone is not produced yet)\n\nBelow 5 on Day 21 = you probably did not ovulate that month.", "fast": "No.\nTest Day 21\n(or 7 days after\novulation).", "retest": "Every 3-6 months", "one": "Timing is everything. Progesterone on Day 3 is useless (it SHOULD be low). Day 21 is the money shot — it shows whether you ovulated and whether your corpus luteum is producing enough. Track your cycle to know when Day 21 is."}, {"n": "Free + Total Testosterone", "cat": "HORMONES", "what": "Testosterone is not just a male hormone. Women need it for energy, libido, muscle maintenance, bone strength, confidence, and mood. Your levels are about 1/10th of a mans, but they matter just as much for how you feel.\n\nTOTAL testosterone = everything (bound + unbound)\nFREE testosterone = the unbound portion that is actually available to your cells (usually only 1-2% of total)\n\nSHBG (a protein in your blood) binds testosterone and makes it inactive. So you can have normal TOTAL testosterone but low FREE testosterone if SHBG is high (common with birth control pills).", "feel": "LOW testosterone in women: fatigue, low libido (not interested in sex, or takes much longer to feel aroused), difficulty building muscle despite training, low motivation and drive, flat mood, brain fog, poor recovery from workouts.\n\nHIGH testosterone: acne (especially jawline and chin), excess facial/body hair, hair thinning on scalp, irregular periods — classic PCOS pattern.", "range": "FREE T optimal: 0.5-2.5 pg/mL\nTOTAL T optimal: 15-70 ng/dL\n\nHigh free T with acne + irregular periods = investigate PCOS\nLow free T with fatigue + low libido = hormonal optimization needed", "fast": "No.\nMorning draw\n8-10am.", "retest": "Every 6 months", "one": "If you have ever been on birth control pills, your SHBG may still be elevated months after stopping, keeping free testosterone low. SHBG (also in your H+ panel) tells you if this is happening. Low libido after stopping the pill is almost always SHBG-related."}, {"n": "SHBG", "cat": "HORMONES", "what": "Sex Hormone Binding Globulin is a protein your liver makes that BINDS sex hormones (testosterone and estrogen) in your blood, making them inactive. Think of SHBG as a parking garage for hormones — while parked, they cannot do their job.\n\nHigh SHBG = more hormones parked = less available for your cells\nLow SHBG = fewer hormones parked = more available (can be too much)\n\nSHBG is why total testosterone alone is misleading. You need to know how much is free vs bound.", "feel": "HIGH SHBG: same symptoms as low testosterone (low libido, fatigue, difficulty building muscle) because even though total T is \"normal,\" most of it is bound and unavailable.\n\nLOW SHBG: more free testosterone and estrogen available — can mean PCOS symptoms (acne, hair growth) or estrogen-dominant symptoms.", "range": "OPTIMAL: 40-120 nmol/L\nLAB: 18-144\n\nAbove 120: too much binding\nBelow 30: too little binding (often PCOS)", "fast": "No. Morning.", "retest": "Every 6 months", "one": "SHBG is the missing piece that explains many hormonal complaints. \"Normal\" total testosterone with high SHBG = effectively low testosterone at the tissue level. Always interpret total T, free T, and SHBG together as a trio."}, {"n": "DHEA-S", "cat": "HORMONES", "what": "DHEA (dehydroepiandrosterone) is a hormone made by your ADRENAL glands (small glands sitting on top of your kidneys). It is the most abundant hormone in your body and serves as a raw material that gets converted into both testosterone and estrogen.\n\nDHEA-S is the sulfated (storage) form — more stable in blood, easier to measure. It peaks around age 25 and then declines about 2% per year. By 40, you have about 30% less than at 25. By 50, about 50% less.\n\nIt is sometimes called the \"youth hormone\" because its decline parallels many aging symptoms.", "feel": "LOW DHEA-S: fatigue, low libido, loss of muscle tone, dry skin, brain fog, weakened immune function, depression, feeling \"old.\" Many symptoms attributed to aging are actually DHEA declining.\n\nHIGH DHEA-S: acne, oily skin, excess hair growth, irregular periods — similar to high testosterone symptoms (because DHEA converts to testosterone). Common in PCOS and adrenal hyperplasia.", "range": "OPTIMAL at age 30: 150-350 μg/dL\nLAB: 35-430\n\nBelow 150 at 30 = adrenals are underperforming\nAbove 400 = investigate PCOS or adrenal issues", "fast": "No. Morning.", "retest": "Every 6 months", "one": "If cortisol is chronically high AND DHEA-S is low, your adrenals are in \"survival mode\" — prioritizing stress response over youth/vitality hormones. Fix the stress first (ashwagandha, sleep, meditation), then DHEA will often recover on its own."}, {"n": "Prolactin", "cat": "HORMONES", "what": "Prolactin is a hormone made by your pituitary gland (a pea-sized gland at the base of your brain). Its primary job is stimulating breast milk production after pregnancy. But outside of pregnancy, prolactin has effects on mood, immunity, and reproductive function.\n\nElevated prolactin outside of pregnancy/breastfeeding = something is stimulating the pituitary. Could be stress, medications, thyroid problems, or rarely a benign pituitary tumor (prolactinoma).", "feel": "HIGH prolactin: irregular or missing periods (prolactin suppresses ovulation), milky nipple discharge even when not pregnant, low libido, headaches, vision changes (if from pituitary tumor pressing on optic nerve — rare but important).\n\nMild elevation: often just from stress — prolactin rises during stress, after exercise, even from breast stimulation.", "range": "OPTIMAL: below 25 ng/mL\nLAB: 4.8-23.3\nMILDLY ELEVATED: 25-50 (usually stress, retest)\nMODERATELY ELEVATED: 50-100 (investigate)\nHIGHLY ELEVATED: above 100 (pituitary MRI recommended)", "fast": "No.\nMorning.\nAvoid stress\nbefore test.", "retest": "Annually", "one": "If prolactin comes back mildly elevated, do not panic. Retest on a different day when you are relaxed. Stress on the morning of the blood draw alone can elevate prolactin 20-40%. If it is consistently elevated, THEN investigate."}, {"n": "FSH + LH", "cat": "HORMONES", "what": "FSH (Follicle Stimulating Hormone) and LH (Luteinizing Hormone) are both made by your pituitary gland and control your menstrual cycle.\n\nFSH: tells your ovaries to start growing egg follicles each month. As your ovarian reserve declines with age, FSH has to \"shout louder\" to get the ovaries to respond — so FSH RISES as you age and approach menopause.\n\nLH: triggers ovulation — the mid-cycle LH surge is what releases the egg.\n\nThe LH:FSH RATIO is diagnostically useful:\n- Normal: roughly 1:1\n- PCOS pattern: LH is 2-3x higher than FSH (LH:FSH ratio above 2:1)", "feel": "You do not feel FSH or LH directly. But what they reveal:\n\nHigh FSH at 30: your ovarian reserve may be declining faster than expected (check AMH to confirm).\n\nHigh LH:FSH ratio: classic PCOS pattern — ovaries are being overstimulated by LH, leading to excess androgen production, cysts, and irregular ovulation.", "range": "FSH Day 3: 3-10 mIU/mL\nAbove 10 at age 30 = investigate ovarian reserve\nAbove 25 = approaching menopause\n\nLH Day 3: 2-15 mIU/mL\nLH:FSH ratio above 2:1 = PCOS pattern", "fast": "No.\nTest Day 3\nof cycle.", "retest": "Annually", "one": "Test BOTH on Day 3 of your cycle and calculate the ratio. LH:FSH above 2:1 is a pattern many women with subtle PCOS have without realizing it. Combined with elevated free testosterone and insulin resistance, it forms the PCOS triad."}, {"n": "Serum Iron + TIBC + Transferrin", "cat": "IRON", "what": "These three tests work TOGETHER to paint the full iron picture. Testing ferritin alone is not enough because ferritin is also an inflammation marker — it can be \"normal\" even when you are iron deficient if you also have inflammation.\n\nSERUM IRON: how much iron is in your blood RIGHT NOW (fluctuates throughout the day)\nTIBC (Total Iron Binding Capacity): how much ROOM there is on iron-transport proteins. When iron is low, your body makes more transport proteins to scavenge whatever iron is available → TIBC goes UP.\nTRANSFERRIN: the actual transport protein that carries iron through blood.\n\nTRANSFERRIN SATURATION (calculate: serum iron ÷ TIBC × 100):\n- Below 20% = iron deficiency\n- Above 45% = iron overload\n- 20-45% = normal", "feel": "Same as ferritin deficiency: fatigue, poor exercise performance, hair loss, cold extremities, brittle nails, restless legs.", "range": "SERUM IRON: 60-170 μg/dL\nTIBC: 250-370 μg/dL\nTRANSFERRIN: 200-360 mg/dL\nSATURATION: 20-45%\n\nClassic iron deficiency pattern:\nLow serum iron + High TIBC + Low saturation + Low ferritin", "fast": "YES. Morning.", "retest": "Every 3-6 months", "one": "The full iron panel (serum iron, TIBC, transferrin, ferritin) interpreted TOGETHER gives you the complete picture. Ferritin alone can be misleading if you have any inflammation (which hs-CRP will tell you)."}, {"n": "Vitamin D (25-OH)", "cat": "VITAMINS", "what": "Vitamin D is not actually a vitamin — it is a HORMONE. Your skin makes it from sunlight, your liver processes it, and your kidneys activate it. It regulates over 1,000 genes and affects virtually every system in your body.\n\nDespite living in SUNNY BALI, many residents and expats are deficient. Why? Sunscreen blocks D production, spending most time indoors (working, restaurants, shops), and the body adapts to constant sun exposure by making less over time.", "feel": "DEFICIENCY: getting sick often (immune dysfunction), bone pain, fatigue, depression, muscle weakness, slow wound healing, hair loss, back pain. Chronic deficiency significantly increases risk of autoimmune disease, cancer, cardiovascular disease, and osteoporosis.\n\nThese symptoms overlap with so many other things that people rarely attribute them to vitamin D.", "range": "OPTIMAL: 40-60 ng/mL\nGOOD: 30-40\nINSUFFICIENT: 20-30\nDEFICIENT: below 20\nTOXIC: above 100 (very rare)\n\nLab says above 30 is \"normal\" but optimal is 40-60.", "fast": "No.", "retest": "Every 6 months", "one": "The combination of D3+K2 is important. K2 directs calcium into bones and teeth instead of arteries. Without K2, supplementing D3 could theoretically promote arterial calcification (although this is debated). You are already taking the combo — smart."}, {"n": "Folic Acid (Folate, B9)", "cat": "VITAMINS", "what": "Folate is a B vitamin essential for DNA repair, cell division, red blood cell production, and methylation (the detox/DNA repair process). It works hand-in-hand with B12 — they are a team.\n\nThe synthetic form (folic acid) is in supplements and fortified foods. The natural form (folate) is in leafy greens, beans, and citrus. Your body must convert folic acid → active methylfolate.\n\n~40% of people have an MTHFR gene variant that slows this conversion. If you have this variant, you should take methylfolate, not folic acid.", "feel": "DEFICIENCY: fatigue, mouth sores, brain fog, mood changes, shortness of breath, pale skin. Similar to B12 deficiency because they work together.\n\nDuring pregnancy: folate deficiency causes neural tube defects (spina bifida). Even outside pregnancy, low folate impairs DNA repair.", "range": "OPTIMAL: above 15 ng/mL\nLAB: 3-20\nDEFICIENT: below 3", "fast": "No.", "retest": "Every 6 months", "one": "If your homocysteine comes back high, check both B12 AND folate — a deficiency in either one raises homocysteine. If both are \"normal\" but homocysteine is still high, you likely have an MTHFR gene variant. Get genetic testing to confirm, then switch to methylated forms."}, {"n": "Zinc", "cat": "VITAMINS", "what": "Zinc is involved in over 300 enzyme reactions in your body. It is critical for: immune function, wound healing, thyroid hormone conversion (T4→T3), testosterone production, skin health, taste and smell, and protein synthesis.\n\nYour body has no zinc storage system — you need daily intake. It is commonly deficient because modern soils are zinc-depleted and many foods contain phytates (grains, legumes) that block zinc absorption.", "feel": "DEFICIENCY: frequent colds and infections (immune dysfunction), slow wound healing, skin problems (acne, dermatitis), hair loss, loss of taste or smell (if you have ever lost taste from illness, that partly involves zinc pathways), poor thyroid conversion, low testosterone/libido.", "range": "OPTIMAL: 70-100 μg/dL\nLAB: 60-120\nDEFICIENT: below 60", "fast": "YES. Morning.", "retest": "Every 6 months", "one": "Zinc + selenium are the two most important minerals for thyroid function and immune health. Neither is in the H+ panel. Together they cost maybe Rp 300-500K at Prodia. Add them."}, {"n": "Selenium", "cat": "VITAMINS", "what": "Selenium is a trace mineral essential for thyroid hormone conversion (T4→T3), antioxidant defense (it is a building block of glutathione peroxidase, one of your most powerful antioxidants), and immune regulation.\n\nIt is also the ONLY supplement proven in clinical trials to lower thyroid antibodies (Anti-TPO) in Hashimotos patients. If your Anti-TPO comes back elevated, selenium is the #1 intervention before medication.", "feel": "DEFICIENCY: poor thyroid function (low FT3 despite normal TSH), weakened immunity, muscle weakness, hair and nail problems, increased cancer risk (selenium plays a role in cancer prevention pathways).", "range": "OPTIMAL: 70-150 ng/mL\nLAB: 70-150\nTOXIC: above 400 (selenosis — hair loss, garlic breath, GI problems, nail changes)", "fast": "YES. Morning.", "retest": "Annually", "one": "Two Brazil nuts daily = 200mcg selenium = the cheapest, most evidence-based thyroid support available. Buy a bag of Brazil nuts from the supermarket. That is your \"prescription.\""}, {"n": "Hepatitis B (HBsAg + Anti-HBs)", "cat": "INFECTIOUS", "what": "Hepatitis B is a virus that attacks your liver. It spreads through blood and body fluids (sexual contact, shared needles, contaminated medical equipment). Southeast Asia has higher prevalence than Western countries.\n\nHBsAg: tests for ACTIVE infection (virus is in your body right now)\nAnti-HBs: tests for IMMUNITY (either from vaccination or from having cleared a past infection)\n\nYou want: HBsAg NEGATIVE (no active infection) + Anti-HBs POSITIVE above 10 (you are immune).", "feel": "Active Hep B: many people have NO symptoms for years while the virus damages their liver. When symptoms appear: fatigue, jaundice (yellow skin/eyes), dark urine, abdominal pain, nausea. Chronic Hep B significantly increases liver cancer risk.", "range": "HBsAg: NEGATIVE (good)\nAnti-HBs: above 10 mIU/mL (immune)\n\nIf Anti-HBs is below 10: you are NOT immune and need a booster vaccination.", "fast": "No.", "retest": "ONE TIME\n(unless new\nexposure risk)", "one": "If your Anti-HBs comes back below 10, get a Hep B booster at any clinic in Bali. It is cheap (Rp 200-500K), quick, and important living in SE Asia. Prodia through their app even offers vaccination."}, {"n": "Hepatitis C (Anti-HCV)", "cat": "INFECTIOUS", "what": "Hepatitis C is another liver virus but it spreads ONLY through blood (not sexual contact in most cases). It was historically transmitted through blood transfusions (before screening), shared needles, tattoos with unsterilized equipment, and contaminated medical instruments.\n\nThe good news: Hep C is now CURABLE. Direct-acting antiviral drugs cure over 95% of cases in 8-12 weeks. This was not possible before 2014.", "feel": "Most people with Hep C have NO symptoms for years or decades while the virus slowly damages their liver. Eventually: fatigue, jaundice, abdominal pain, cirrhosis, liver cancer.\n\nMany people discover they have Hep C only during routine screening.", "range": "NEGATIVE = never had Hep C\nPOSITIVE = past or current infection (need confirmatory RNA test to see if virus is still active)", "fast": "No.", "retest": "ONE TIME", "one": "If you have ever gotten a tattoo (including in Bali where sterilization practices vary), this test is worth doing once. Hep C is curable but must be caught."}, {"n": "HIV Ab/Ag Combi", "cat": "INFECTIOUS", "what": "4th generation HIV test detects both antibodies (your immune response to HIV) and antigen (the virus itself). This dual detection makes it the most accurate screening test — it can detect HIV as early as 2-6 weeks after exposure.\n\nHIV is no longer a death sentence. With modern antiretroviral therapy, people with HIV live normal lifespans. But you need to know your status to get treatment.", "feel": "Early HIV: many people have a flu-like illness 2-4 weeks after infection (fever, fatigue, rash, sore throat) that resolves on its own. Then NOTHING for years while the virus gradually weakens the immune system. Without treatment: eventually AIDS (immune system failure, opportunistic infections).", "range": "NEGATIVE = no HIV detected\nPOSITIVE = confirmatory test needed (Western blot)", "fast": "No.", "retest": "ONE TIME\n(unless new risk)", "one": "Standard baseline screening. Recommended for everyone at least once in their life regardless of perceived risk."}, {"n": "H. Pylori", "cat": "INFECTIOUS", "what": "Helicobacter pylori is a bacteria that lives in your STOMACH. It burrows into the stomach lining and causes chronic inflammation. Over years, this can lead to: gastritis, stomach ulcers, and even stomach CANCER.\n\nMore than 50% of people in Southeast Asia are infected. Most do not know it. You can pick it up from contaminated food, water, or person-to-person contact (common in childhood).\n\nJapan includes H. pylori testing in their standard Ningen Dock because stomach cancer is the #3 cause of cancer death in Asia.", "feel": "Most infected people have NO symptoms. Some develop: chronic indigestion, bloating, burning stomach pain (especially when stomach is empty), nausea, loss of appetite, frequent burping.\n\nSilent H. pylori infection increases stomach cancer risk 6-fold over decades.", "range": "NEGATIVE = not infected\nPOSITIVE = infected, treatment recommended", "fast": "YES for\nbreath test.", "retest": "ONCE.\nRetest after\ntreatment.", "one": "Living in Bali with >50% regional prevalence, this is worth testing once. The breath test is the most accurate non-invasive method. If positive, treatment is straightforward and eliminates a hidden inflammation source. Japan tests everyone for this — there is a reason."}, {"n": "CA-125", "cat": "CANCER MARKERS", "what": "CA-125 is a protein that ovarian cancer cells produce in large amounts. It is used as a SCREENING marker for ovarian cancer, though it is not perfect — other conditions also raise it.\n\nImportant context: ovarian cancer is the 5th leading cause of cancer death in women. It is called the \"silent killer\" because symptoms are vague and easily dismissed until the cancer is advanced.", "feel": "Ovarian cancer symptoms (often attributed to other things): persistent bloating, pelvic pain, feeling full quickly, urinary urgency. These are vague, which is why screening matters.\n\nElevated CA-125 does NOT automatically mean cancer. It is also elevated in: endometriosis, fibroids, PID, menstruation, pregnancy, liver disease.", "range": "NORMAL: below 35 U/mL\n\nMildly elevated (35-65): often benign causes. Monitor and repeat.\nSignificantly elevated (above 65): further investigation needed (pelvic ultrasound + gynecologist).", "fast": "No.\nAvoid testing\nduring period.", "retest": "Annually", "one": "Do NOT test during your period or the few days before — menstruation alone can elevate CA-125 and cause unnecessary anxiety. Test mid-cycle for accuracy."}, {"n": "DEXA Scan", "cat": "BODY SCANS", "what": "DEXA stands for Dual-Energy X-ray Absorptiometry. It is a low-radiation scan that takes 10 minutes while you lie on a table. It measures THREE things simultaneously:\n\n1. BODY FAT % (total and regional — shows exactly where fat is distributed)\n2. LEAN MUSCLE MASS (total and per limb — shows muscle imbalances)\n3. BONE DENSITY (T-score — screens for osteoporosis)\n\nPlus: it estimates VISCERAL FAT (the dangerous fat around your organs that you cannot see from outside). This is the most medically important body composition metric.\n\nNo other test gives you all three in one scan.", "feel": "You do not \"feel\" body composition, but it determines everything: metabolic health, hormonal status, disease risk, athletic performance, and how you look.\n\nSpecific to your situation: reta causes weight loss, but is it FAT loss or MUSCLE loss? The scale cannot tell you. DEXA can. If you are losing muscle on reta, you need to adjust protein intake and training.", "range": "BODY FAT women 30: 20-30% (fitness range)\nVISCERAL FAT: as low as possible\nBONE T-SCORE: above -1.0 (normal)\n-1.0 to -2.5 = osteopenia\nbelow -2.5 = osteoporosis", "fast": "No.", "retest": "Every 6-12\nmonths", "one": "Worth a trip to Jakarta or Bangkok specifically for this. Costs $50-150. Shows you things no blood test can: are you actually losing fat or cannibalizing muscle on reta? Is your bone density healthy at 30? Where exactly is your visceral fat?"}, {"n": "VO2 Max", "cat": "FITNESS", "what": "VO2 max measures the maximum amount of oxygen your body can use during intense exercise. It is tested by wearing a mask that analyzes your breath while running on a treadmill or cycling at increasing intensity until exhaustion.\n\nWhy it matters: VO2 max is the SINGLE STRONGEST PREDICTOR of how long you will live. Stronger correlation than smoking, blood pressure, cholesterol, or diabetes.\n\nPeople in the top 25% of VO2 max for their age have 5x LOWER risk of dying from any cause compared to the bottom 25%. That is a bigger effect than almost any drug or intervention.", "feel": "You cannot \"feel\" your VO2 max directly. But low cardiorespiratory fitness manifests as: getting winded easily, poor exercise tolerance, slow recovery, fatigue during moderate activities.\n\nHigh VO2 max feels like: effortless everyday activities, good energy throughout the day, ability to sustain moderate exercise indefinitely.", "range": "FEMALE AGE 30:\nPoor: below 30 mL/kg/min\nAverage: 30-35\nGood: 35-40\nExcellent: 40-45\nElite: above 45", "fast": "Avoid big meal\n2hr before.", "retest": "Annually", "one": "Your Lagree and weights are great for strength and body composition. But they do not maximally build VO2 max. Adding zone 2 cardio (brisk walking, cycling, swimming at conversational pace) 4+ hours per week is the highest-impact longevity intervention available. Higher ROI than any supplement."}, {"n": "23andMe + SelfDecode (Genetic Panel)", "cat": "DNA & GENETIC", "what": "Your DNA is the instruction manual your body runs on. It does not change throughout your life. A genetic test reads hundreds of key variations in your DNA that affect:\n\n- Disease risk (BRCA1/2 for breast/ovarian cancer, ApoE4 for Alzheimers)\n- How you process nutrients (MTHFR affects B vitamin metabolism, VDR affects vitamin D)\n- How you metabolize drugs and supplements (CYP enzymes — are you a fast or slow metabolizer?)\n- Predispositions (lactose tolerance, caffeine sensitivity, saturated fat response)\n\n23andMe ($100) gives you the raw data. Upload it to SelfDecode or Promethease ($20-50) for deep analysis of hundreds of genetic variants.", "feel": "You do not feel your genetics directly. But they explain patterns:\n- Why some people thrive on keto and others do not (FTO, PPARG genes)\n- Why some people are anxiety-prone (COMT gene)\n- Why some people need methylated B vitamins (MTHFR gene)\n- Why some people have higher breast cancer risk (BRCA gene)", "range": "Not a number — it is a map of your genetic predispositions.\n\nKey variants to look for:\nBRCA1/2: breast/ovarian cancer risk\nMTHFR: methylation/B vitamin processing\nApoE4: Alzheimers risk\nCOMT: stress hormone processing\nCYP variants: drug metabolism speed", "fast": "No.", "retest": "ONCE in your\nentire life.\nLifetime data.", "one": "This is a $120-200 one-time investment that gives you PERMANENT information about your body. Order 23andMe, spit in the tube, mail it, then upload raw data to SelfDecode ($30) for the deep analysis. The MTHFR result alone changes your supplement strategy permanently."}, {"n": "Biological Age (TruAge)", "cat": "DNA & GENETIC", "what": "Your chronological age is how many birthdays you have had. Your BIOLOGICAL age is how old your cells actually are based on their DNA methylation patterns.\n\nDNA methylation is like a layer of Post-it notes on your DNA that changes based on your lifestyle. Exercise, sleep, diet, stress, pollution — everything leaves marks on your DNA methylation pattern. These marks can be read to calculate how fast you are aging.\n\nSome people are chronologically 30 but biologically 25 (aging slower). Others are 30 but biologically 38 (aging faster). The difference is lifestyle and environment.", "feel": "You cannot feel your biological age. But it predicts your disease risk and lifespan better than any single biomarker.\n\nIf your biological age is LOWER than your chronological age: your lifestyle and interventions are working. You are aging slower than average.\n\nIf HIGHER: something is accelerating your aging. Time to investigate what (stress? sleep? diet? inflammation?).", "range": "IDEAL: biological age lower than chronological age\n\nEvery year of biological age below chronological = meaningful risk reduction.", "fast": "No.", "retest": "Every 6-12\nmonths", "one": "TruDiagnostic TruAge is the gold standard ($300-500, mail-in). This is the one test that answers \"is EVERYTHING I am doing — peptides, supplements, training, diet — actually making me biologically younger?\" Do it before your protocol has been running long, then again at 6-12 months."}, {"n": "GI-MAP (Comprehensive Stool Test)", "cat": "GUT HEALTH", "what": "A GI-MAP uses PCR technology (same tech as COVID tests) to analyze a stool sample for: every type of bacteria in your gut (beneficial and pathogenic), parasites (very relevant in Bali), candida/fungal overgrowth, H. pylori, inflammation markers (calprotectin), digestive function markers, and immune markers.\n\nYour gut contains TRILLIONS of bacteria that affect: immune function (70% of your immune system is in your gut), mood and mental health (gut produces 90% of serotonin), nutrient absorption, inflammation, weight management, and hormone metabolism.\n\nLiving in Bali with tropical water, food handling practices, and environmental exposure, your gut is dealing with things most Western-raised people have not encountered.", "feel": "Gut dysfunction manifests as: bloating, irregular bowel movements, food sensitivities, skin problems (acne, eczema), brain fog, mood issues, autoimmune tendencies, difficulty losing weight despite doing everything right, nutrient deficiencies despite supplementing.\n\nParasites specifically: GI symptoms, fatigue, unexplained weight changes, elevated eosinophils on CBC, iron deficiency, B12 deficiency.", "range": "Results show specific organisms with reference ranges. No single number — it is a map of your gut ecosystem.", "fast": "N/A.\nHome stool\ncollection.", "retest": "Once, or if\nGI symptoms.", "one": "Living in Bali for an extended time = high probability of having encountered parasites. If your eosinophils are elevated on CBC, or you have unexplained GI symptoms, bloating, or nutrient deficiencies despite supplementing, a GI-MAP is the diagnostic deep dive. Order through a functional medicine practitioner via telehealth."}, {"n": "Pap Smear + HPV Test", "cat": "WOMEN", "what": "A Pap smear collects cells from your cervix (the entrance to your uterus) and examines them under a microscope for precancerous changes. The HPV test checks for high-risk strains of human papillomavirus that CAUSE cervical cancer.\n\nCervical cancer is almost entirely caused by HPV (a sexually transmitted virus). It takes 10-20 years to develop from HPV infection to cancer, which means screening catches it LONG before it becomes dangerous.\n\nCervical cancer is one of the most PREVENTABLE cancers if screened regularly.", "feel": "HPV infection: usually NO symptoms. Your body clears most HPV infections on its own within 1-2 years.\n\nPrecancerous changes: NO symptoms (that is why screening matters).\n\nAdvanced cervical cancer: abnormal bleeding (between periods, after sex), pelvic pain, unusual discharge.", "range": "PAP result: Normal, ASCUS (unclear), LSIL (mild changes), HSIL (serious changes — need colposcopy)\nHPV result: Positive or Negative for high-risk strains", "fast": "N/A.", "retest": "Every 1-3 years", "one": "This is basic preventive care that saves lives. If you have not had a Pap + HPV test recently, add it to your next screening. Also ask about HPV vaccination if you have not been vaccinated — it is effective even in your 30s for strains you have not yet encountered."}, {"n": "Breast Ultrasound", "cat": "WOMEN", "what": "A breast ultrasound uses sound waves to create images of breast tissue. It detects lumps, cysts, and structural abnormalities that you or a doctor might not be able to feel by hand.\n\nFor women UNDER 40, ultrasound is preferred over mammography because younger women have DENSER breast tissue. Dense tissue appears white on mammograms — and so do tumors. So mammograms in young women have more false negatives (missing real problems) and false positives (flagging things that are not problems). Ultrasound handles dense tissue much better.\n\nAfter 40, mammography becomes more useful as breast tissue becomes less dense.", "feel": "Breast cancer early symptoms: painless lump (most common), changes in breast shape or size, skin dimpling, nipple discharge, redness or thickening.\n\nBut early-stage breast cancer usually has NO symptoms — which is why screening exists.", "range": "BIRADS scoring:\n1 = negative (normal)\n2 = benign finding (cyst, etc.)\n3 = probably benign (6-month follow-up)\n4 = suspicious (biopsy recommended)\n5 = highly suspicious (biopsy urgent)", "fast": "N/A.", "retest": "Annually from\nage 30", "one": "Breast cancer is the #1 cancer in women globally. Starting annual ultrasound screening at 30 is proactive, especially if you have any family history. A 15-minute scan could catch something early enough to be cured. Available at BIMC Bali for Rp 500K-1M."}, {"n": "Pelvic Ultrasound", "cat": "WOMEN", "what": "A pelvic ultrasound images your uterus and ovaries using sound waves. It can be done two ways:\n- Abdominal (wand on your belly — requires full bladder)\n- Transvaginal (wand inserted vaginally — more detailed, no full bladder needed)\n\nTransvaginal is more accurate for ovarian assessment but some women prefer abdominal for comfort.\n\nThis screens for: ovarian cysts, uterine fibroids, polyps, endometriosis, and structural abnormalities. These are extremely COMMON in women — up to 70% of women will have fibroids by age 50.", "feel": "Ovarian cysts: often no symptoms. Large cysts can cause pelvic pain, bloating, pain during sex.\n\nFibroids: heavy periods, pelvic pressure, frequent urination, pain. Many women have fibroids with zero symptoms.\n\nEndometriosis: severe period pain, pain during sex, chronic pelvic pain, infertility.", "range": "Normal: no masses, normal uterine size and shape, normal ovarian appearance.\n\nFindings: cysts (most are benign and resolve on their own), fibroids (tracked by size), polyps (may need removal), endometriomas.", "fast": "Full bladder\nfor abdominal.", "retest": "Every 2-3 years", "one": "At RSUD Bali Mandara this costs around Rp 188-280K. At BIMC probably Rp 500K-1M. Worth doing once for baseline."}, {"n": "Skin Check (Dermatoscopy)", "cat": "PREVENTIVE", "what": "A dermatologist examines every mole on your body using a dermatoscope — a handheld magnifying device with polarized light that reveals structures beneath the skin surface invisible to the naked eye.\n\nMelanoma (the most dangerous skin cancer) is nearly 100% curable if caught early and nearly 100% fatal if caught late. The difference between early and late is often just ONE screening appointment.\n\nLiving in Bali with year-round intense UV exposure significantly elevates your melanoma risk.", "feel": "Melanoma warning signs (ABCDE rule):\nA = Asymmetry (one half does not match the other)\nB = Border (irregular, scalloped edges)\nC = Color (multiple colors in one mole)\nD = Diameter (larger than 6mm/pencil eraser)\nE = Evolving (changing in size, shape, or color)\n\nBut early melanomas can look normal to untrained eyes — a dermatoscope catches what you cannot.", "range": "No suspicious lesions = clear.\nDysplastic nevi (atypical moles) = monitor closely, photograph for comparison.\nSuspicious = biopsy to confirm or rule out melanoma.", "fast": "N/A.", "retest": "ANNUALLY.\nNon-negotiable\nin tropical\nclimate.", "one": "This is the preventive screening that could literally save your life with the least effort. 15-minute appointment, annually. In Australia (highest melanoma rate globally), annual skin checks are considered standard care. Living in equivalent UV exposure in Bali, you should follow the same standard."}, {"n": "Eye Exam", "cat": "PREVENTIVE", "what": "A comprehensive eye exam is more than checking if you need glasses. An ophthalmologist measures:\n\n- Intraocular pressure (high pressure = glaucoma risk, which silently destroys peripheral vision)\n- Retinal imaging (the back of your eye is the ONLY place in your body where blood vessels can be directly observed without surgery — changes here can reveal diabetes, hypertension, and neurological problems BEFORE other tests catch them)\n- Visual acuity, color vision, peripheral vision\n\nYour eyes are literally windows into your systemic health.", "feel": "Glaucoma: COMPLETELY silent until significant vision loss (peripheral vision slowly narrows like a tunnel). Irreversible once lost.\n\nDiabetic retinal changes: no symptoms until advanced.\n\nMacular degeneration: central vision gradually blurs.", "range": "Normal pressure: 12-22 mmHg\nNormal retina: no hemorrhages, exudates, or vessel changes.\nNormal vision: correctable to 20/20.", "fast": "N/A.", "retest": "Annually", "one": "Retinal imaging is the cheapest, fastest way to see your blood vessels directly. Changes here can predict cardiovascular disease and diabetes before traditional markers. Worth doing annually — quick, painless, informative."}, {"n": "Dental X-ray + Cleaning", "cat": "PREVENTIVE", "what": "Oral health is directly connected to systemic health in ways most people do not realize. Periodontitis (gum disease) is a chronic bacterial infection that causes:\n\n- Chronic low-grade inflammation that raises hs-CRP and cardiovascular risk\n- Bacteria entering your bloodstream through inflamed gums\n- Documented increased risk of heart disease, stroke, diabetes complications, and preterm birth\n\nRegular professional cleaning removes calculus (hardened plaque) that you cannot remove with brushing alone. Panoramic X-ray every 1-2 years checks for cavities, bone loss, impacted wisdom teeth, and jaw abnormalities.", "feel": "Gum disease symptoms: bleeding gums when brushing/flossing, persistent bad breath, red or swollen gums, receding gums, loose teeth (advanced).\n\nMany people have gum disease and do not know it — they assume bleeding gums are \"normal.\" They are not.", "range": "Healthy: no bleeding on probing, no pockets deeper than 3mm, no bone loss on X-ray.\n\nGingivitis: reversible gum inflammation.\nPeriodontitis: irreversible bone loss (manageable but not reversible).", "fast": "N/A.", "retest": "Every 6 months", "one": "If your hs-CRP is elevated and you cannot figure out why — and you have not had a dental cleaning in over a year — gum disease may be the hidden culprit. This is one of the most overlooked inflammation sources in health optimization."}];
